window.PDD_DATA = window.PDD_DATA || [];
window.PDD_DATA = window.PDD_DATA.concat([{"num": 148, "text": "Что означает этот сигнал сотрудника Гарды?", "topic": "Дорожні знаки та розмітка", "options": ["Остановитесь при подъезде спереди.", "Продолжайте движение при подъезде спереди.", "Продолжайте движение при подъезде сзади.", "Остановитесь при подъезде сзади."], "correct": 0, "expl": "Сигнали регулювальника (Гарди) мають вищий пріоритет за будь-які знаки чи світлофори. Підняту вертикально руку, звернену долонею до водія, що наближається спереду, завжди слід читати як команду СТОП саме для цього напрямку.", "explSpecific": "Правильно — «Остановитесь при подъезде спереди»: регулювальник дивиться на вас, тож сигнал стосується вашого, переднього щодо нього, напрямку. «Продовжуйте рух спереду/ззаду» суперечать самій суті піднятої руки як сигналу зупинки; «зупиніться ззаду» стосується протилежного, не вашого напрямку підʼїзду.", "img": "q148.png"}, {"num": 149, "text": "Что означает этот сигнал сотрудника Гарды?", "topic": "Дорожні знаки та розмітка", "options": ["Поверните на право.", "Поверните налево.", "Остановитесь при подъезде спереди.", "Остановитесь при подъезде сзади."], "correct": 3, "expl": "Той самий регулювальник, стоячи боком, може окремо адресувати сигнал транспорту, що наближається саме ззаду відносно напрямку, куди він дивиться.", "explSpecific": "Правильно — «Остановитесь при подъезде сзади». «Поверніть праворуч/ліворуч» вигадують сигнали повороту, яких немає в цій позі регулювальника; «зупиніться спереду» стосується протилежного напрямку.", "img": "q149.png"}, {"num": 150, "text": "Что означает этот сигнал сотрудника Гарды?", "topic": "Дорожні знаки та розмітка", "options": ["Поверните направо.", "Поверните налево.", "Остановитесь при подъезде спереди или сзади.", "Продолжайте движение при подъезде спереди."], "correct": 2, "expl": "Коли регулювальник стоїть, розкинувши обидві руки в сторони, це універсальний сигнал зупинки для транспорту з обох поздовжніх напрямків одразу.", "explSpecific": "Правильно — «Остановитесь при подъезде спереди или сзади» (обидві руки в сторони — сигнал для обох напрямків). «Праворуч/ліворуч» вигадують сигнали повороту; «продовжуйте рух спереду» суперечить позі регулювальника із розкинутими руками, яка завжди означає зупинку.", "img": "q150.png"}, {"num": 151, "text": "Что означает этот сигнал сотрудника Гарды?", "topic": "Дорожні знаки та розмітка", "options": ["Водитель не должен поворачивать налево.", "Сотрудник Гарды пропускает транспорт, приближающийся спереди.", "Водитель не должен поворачивать направо.", "Сотрудник Гарды пропускает транспорт, приближающийся с любой стороны."], "correct": 3, "expl": "Коли регулювальник стоїть боком, з витягнутою вбік рукою, він пропускає той потік, паралельно якому стоїть, зупиняючи перпендикулярний.", "explSpecific": "Правильно — «Сотрудник Гарды пропускает транспорт, приближающийся с любой стороны» (бокова стійка відкриває обидва паралельні напрямки одночасно). «Не повертати ліворуч/праворуч» вигадують заборони поворотів, не показані позою регулювальника; «пропускає лише спереду» звужує сигнал до одного напрямку.", "img": "q151.png"}, {"num": 152, "text": "Что означает этот сигнал сотрудника Гарды?", "topic": "Дорожні знаки та розмітка", "options": ["Транспорт, едущий спереди, должен остановится.", "Транспорт, едущий спереди, может продолжить движение.", "Транспорт, едущий сзади, должен остановиться.", "Транспорт, едущий справа, может продолжить движение."], "correct": 1, "expl": "Коли регулювальник опускає раніше підняту руку чи подає рух рукою вперед у напрямку транспорту, це сигнал дозволу проїзду для цього напрямку.", "explSpecific": "Правильно — «Транспорт, едущий спереди, может продолжить движение». «Спереду зупинитися» суперечить жесту дозволу руху; «ззаду зупинитися/продовжити» стосуються протилежного, не переднього напрямку сигналу.", "img": "q152.png"}, {"num": 153, "text": "Что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Участок обеспечения принудительного снижения скорости.", "Остановка безопасности.", "Пешеходный переход с разметкой типа “зебра”.", "Велосипедная дорожка."], "correct": 2, "expl": "Дорожня розмітка з широкими білими смугами впоперек проїзної частини — це пішохідний перехід типу «зебра», де пішоходи мають пріоритет, щойно ступили на перехід.", "explSpecific": "Правильно — «Пешеходный переход с разметкой типа зебра». «Ділянка примусового зниження швидкості» і «безпечна зупинка» — geть інші за призначенням елементи розмітки; «велосипедна доріжка» позначається суцільною чи переривчастою лінією з піктограмою велосипеда, а не широкими смугами.", "img": "q153.png"}, {"num": 154, "text": "Что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Зона высадки для такси.", "Транспортные средства не должны въезжать на такой участок при невозможности объехать его без остановки или при повороте направо.", "Транспортные средства, въезжающие на такой участок справа и слева имеют преимущественное право движения, если они не продолжают движение прямо.", "Транспортные средства, въезжающие на такой участок имеют преимущественное право движения перед транспортом, едущим справа и слева."], "correct": 1, "expl": "Жовта сітчаста розмітка (box junction) на перехресті забороняє в'їзд на неї, якщо водій не зможе виїхати без зупинки всередині, окрім випадку повороту праворуч в очікуванні зустрічного потоку.", "explSpecific": "Правильно — варіант про заборону в'їзду за неможливості звільнити ділянку без зупинки (крім повороту праворуч). Варіанти про зону висадки таксі чи взаємний пріоритет в'їжджаючих з боків вигадують геть інше призначення жовтої сітчастої розмітки.", "img": "q154.png"}, {"num": 155, "text": "Что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Водитель может совершать обгон на этом участке.", "Неровная дорожная поверхность.", "Участок предназначен только для высадки.", "Стоянка на этом участке запрещена."], "correct": 3, "expl": "Штрихована розмітка вздовж узбіччя чи острівця безпеки зазвичай означає заборону стоянки чи заїзду на цю ділянку.", "explSpecific": "Правильно — «Стоянка на этом участке запрещена». «Обгін можна» і «лише для висадки» вигадують дозвільне призначення, протилежне заборонному сенсу штрихування; «нерівна поверхня» — geть інша, не розміточна, а фізична характеристика дороги.", "img": "q155.png"}, {"num": 156, "text": "Что означает эта дорожная разметка и информационная табличка вместе?", "topic": "Дорожні знаки та розмітка", "options": ["Стоянка такси в указанное время.", "Стоянка запрещена в указанное время.", "Стоянка запрещена в любое время.", "Погрузочная платформа работает в указанное время."], "correct": 1, "expl": "Комбінація дорожньої розмітки (зазвичай жовтих ліній) та інформаційної таблички з часом означає, що заборона стоянки діє саме у вказані години, а не завжди.", "explSpecific": "Правильно — «Стоянка запрещена в указанное время». «Стоянка такси в указанное время» і «погрузочная платформа» вигадують інше призначення, не властиве жовтій забороняючій розмітці; «заборонено завжди» суперечить наявності таблички з конкретним часом.", "img": "q156.png"}, {"num": 157, "text": "Что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Стоянка вдоль этой дороги запрещена.", "Запрещается пересекать прерывистую белую линию в случае опасности.", "Обгон вдоль этой дороги запрещен.", "Обгон разрешен при условии не пересечения прерывистой белой линии."], "correct": 1, "expl": "Переривчаста біла лінія розмітки в цілому дозволяє перетин за умови безпеки (наприклад, для обгону), на відміну від суцільної, яка перетин забороняє завжди.", "explSpecific": "Правильно — варіант про заборону перетину переривчастої лінії саме в небезпечній ситуації (тобто за безпечних умов перетин дозволений — базове правило переривчастої лінії). «Стоянка вздовж дороги заборонена» і «обгін вздовж дороги заборонено» описують геть інше, не пов'язане з характером самої лінії, призначення.", "img": "q157.png"}, {"num": 158, "text": "Что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Водители должны держаться слева от сплошной белой линии.", "Встречный транспортный поток может пересечь линию для обгона.", "Водители могут пересечь линию для обгона.", "Только мотоциклисты могут пересечь линию для обгона."], "correct": 0, "expl": "Суцільна біла лінія розмітки означає, що перетинати чи виїжджати на протилежний бік від неї заборонено — водії завжди залишаються зі свого боку.", "explSpecific": "Правильно — «Водители должны держаться слева от сплошной белой линии». «Зустрічний потік може перетнути» і «водії можуть перетнути» прямо суперечать забороняючому характеру суцільної лінії; «лише мотоциклісти можуть» вигадує виняток, якого немає в правилі суцільної лінії.", "img": "q158.png"}, {"num": 159, "text": "Что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Обгон разрешен.", "Водитель подъезжает к знаку”Stop”.", "Впереди сужение дороги.", "Весь транспортный поток должен оставаться слева от белой линии."], "correct": 3, "expl": "Подвійна чи посилена суцільна лінія розмітки вимагає, щоб увесь транспортний потік залишався зі свого боку без винятків.", "explSpecific": "Правильно — «Весь транспортный поток должен оставаться слева от белой линии». «Обгін дозволено» прямо суперечить забороняючому сенсу суцільної лінії; «під'їжджає до стоп» і «звуження дороги» не пов'язані з характером самої лінійної розмітки.", "img": "q159.png"}, {"num": 160, "text": "Что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди сплошные белые линии.", "Стоянка запрещена.", "Впереди проезжая часть с двусторонним движением.", "Обгон запрещен."], "correct": 0, "expl": "Знак чи розмітка, що попереджає про наближення суцільних білих ліній, готує водія до ділянки, де обгін і перетин будуть заборонені.", "explSpecific": "Правильно — «Впереди сплошные белые линии». «Стоянка заборонена» і «обгін заборонено» описують наслідок, а не сам попереджувальний знак про наближення розмітки; «проїжджа частина з двостороннім рухом» — geть інший за темою символ.", "img": "q160.png"}, {"num": 161, "text": "При проезде из пункта А в пункт В, что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди сужение дороги.", "Впереди проезжая часть с двусторонним движением.", "Обгон запрещен.", "Обгон разрешен, если это безопасно."], "correct": 3, "expl": "На ділянці з переривчастою лінією, що переходить в іншу розмітку між двома пунктами, обгін дозволений саме за умови безпеки — це базовий сенс переривчастої лінії.", "explSpecific": "Правильно — «Обгон разрешен, если это безопасно». «Звуження» і «двостороннє» описують геть інший тип знаку; «обгін заборонено» прямо суперечить дозвільному характеру переривчастої лінії.", "img": "q161.png"}, {"num": 162, "text": "При проезде из пункта А в пункт В, что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Водитель может пересечь линии для обгона.", "Встречный транспортный поток не может пересекать линии для обгона.", "Только мотоциклисты могут пересечь.", "Водитель не может пересечь линии для обгона."], "correct": 3, "expl": "На ділянці з подвійною суцільною лінією між двома пунктами обгін і перетин заборонені для обох напрямків руху без винятків.", "explSpecific": "Правильно — «Водитель не может пересечь линии для обгона». «Може перетнути» і «лише мотоциклісти можуть» прямо суперечать забороняючому характеру подвійної суцільної лінії; «зустрічний не може» звужує заборону лише до одного боку, хоча вона стосується обох.", "img": "q162.png"}, {"num": 163, "text": "Что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Впереди тупик.", "Пешеходный переход.", "Проезд частных транспортных средств запрещен.", "Въезд запрещен."], "correct": 3, "expl": "Розмітка чи знак на проїзній частині може дублювати заборону в'їзду там, де стандартний круглий знак «в'їзд заборонено» важко розмістити чи побачити завчасно.", "explSpecific": "Правильно — «Въезд запрещен». «Тупик» і «пішохідний перехід» описують геть інші за призначенням елементи; «приватні ТЗ заборонено» звужує заборону лише до однієї категорії транспорту, хоча вона стосується всіх.", "img": "q163.png"}, {"num": 164, "text": "Что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Стоянка запрещена в рабочие часы.", "Стоянка только для такси.", "Держитесь вне желтых линий.", "Стоянка запрещена в любое время."], "correct": 3, "expl": "Жовті лінії вздовж краю проїзної частини — це розмітка обмеження стоянки; подвійна жовта лінія означає заборону стоянки в будь-який час, без винятків за часом доби.", "explSpecific": "Правильно — «Стоянка запрещена в любое время» (подвійна жовта лінія). «Заборонено в робочі години» і «лише для таксі» описують поодиноку жовту лінію з табличкою часу, а не подвійну; «поза жовтими лініями» неточно трактує саму розмітку як просторову межу, а не заборону в часі.", "img": "q164.png"}, {"num": 165, "text": "Что означает прерывистая желтая дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Стоянка запрещена в любое время.", "Край проезжей части или твердая обочина.", "Полоса медленного движения для тяжелых транспортных средств.", "Остановка разрешена только в случае чрезвычайных ситуаций."], "correct": 1, "expl": "Переривчаста жовта лінія вздовж краю проїзної частини позначає межу твердої узбіччя чи краю дороги, а не заборону стоянки.", "explSpecific": "Правильно — «Край проезжей части или твердая обочина». «Стоянка заборонена завжди» описує суцільну подвійну жовту лінію, а не переривчасту; «смуга повільного руху» і «зупинка лише в екстрених випадках» вигадують інше призначення, не властиве цій розмітці.", "img": "q165.png"}, {"num": 166, "text": "Что означает этот сигнал светофора?", "topic": "Дорожні знаки та розмітка", "options": ["Приготовьтесь к движению.", "Остановитесь, если это безопасно.", "Светофор неисправен.", "Продолжайте движение, если дорога свободна."], "correct": 1, "expl": "Жовтий сигнал світлофора після зеленого попереджає про наближення червоного і вимагає зупинки, якщо це можна зробити безпечно, а не проїзду на все ще жовтий.", "explSpecific": "Правильно — «Остановитесь, если это безопасно». «Приготуйтеся до руху» описує протилежну фазу; «світлофор несправний» і «продовжуйте рух якщо вільно» суперечать стандартному значенню жовтого сигналу як команди готуватися зупинитись.", "img": "q166.png"}, {"num": 167, "text": "Что означает этот сигнал светофора?", "topic": "Дорожні знаки та розмітка", "options": ["Водитель может двигаться в направлении зеленой стрелки, если путь свободен.", "Поворот направо запрещен.", "Водитель должен остановиться и дождаться, пока не загорится также зеленый свет светофора, после чего продолжить движение.", "Весь транспорт должен повернуть направо."], "correct": 0, "expl": "Зелена стрілка світлофора дозволяє рух саме в напрямку стрілки за умови вільного шляху, незалежно від кольору основного (круглого) сигналу поруч.", "explSpecific": "Правильно — «Водитель может двигаться в направлении зеленой стрелки, если путь свободен». «Поворот праворуч заборонено» прямо суперечить дозвільному сенсу зеленої стрілки; «чекати на круглий зелений» і «весь транспорт повинен повернути» вигадують додаткові умови чи накази, яких стрілка не містить.", "img": "q167.png"}, {"num": 168, "text": "Что означает этот сигнал светофора?", "topic": "Дорожні знаки та розмітка", "options": ["Весь транспорт должен повернуть налево.", "Транспорт, поворачивающий налево, может продолжить движение, если дорога свободна.", "Транспорт, поворачивающий налево, должен дождаться, пока не загорится также зеленый свет светофора, после чего продолжить движение.", "Поворот транспорта направо запрещен."], "correct": 1, "expl": "Мигаюча чи додаткова зелена стрілка ліворуч дозволяє поворот ліворуч за сприятливих умов, тоді як інший транспорт, що повертає ліворуч без стрілки, керується загальним сигналом.", "explSpecific": "Правильно — «Транспорт, поворачивающий налево, может продолжить движение, если дорога свободна». «Весь транспорт повинен повернути ліворуч» і «заборона повороту праворуч» вигадують накази, не пов'язані зі стрілкою; «чекати на зелений круглий» суперечить дозвільному сенсу окремої стрілки.", "img": "q168.png"}, {"num": 169, "text": "Что означает этот сигнал светофора?", "topic": "Дорожні знаки та розмітка", "options": ["Транспорт должен остановиться на светофоре.", "Транспорт может продолжить движение, но не поворачивать на право.", "Уступить дорогу встречному транспортному потоку, поворачивающему на право.", "Транспорт может продолжить движение, если дорога свободна."], "correct": 0, "expl": "Червоний сигнал світлофора завжди вимагає повної зупинки транспорту перед перехрестям, незалежно від напрямку майбутнього руху.", "explSpecific": "Правильно — «Транспорт должен остановиться на светофоре». «Може продовжити без повороту праворуч», «поступитися зустрічному» і «продовжити якщо вільно» описують сигнали дозволу, а не червоний.", "img": "q169.png"}, {"num": 170, "text": "Что означает этот сигнал светофора?", "topic": "Дорожні знаки та розмітка", "options": ["Транспорт должен остановиться на светофоре.", "Транспорт может продолжить движение, но не поворачивать на право.", "Уступить дорогу встречному транспортному потоку, поворачивающему на право.", "Транспорт может продолжить движение, если дорога свободна."], "correct": 3, "expl": "Зелений сигнал світлофора дозволяє рух, якщо шлях дійсно вільний і безпечний, а не автоматично за будь-яких умов.", "explSpecific": "Правильно — «Транспорт может продолжить движение, если дорога свободна». «Повинен зупинитися» описує протилежний, червоний сигнал; «не повертати праворуч» і «поступитися зустрічному, що повертає праворуч» вигадують обмеження, не властиві звичайному зеленому сигналу без додаткової стрілки.", "img": "q170.png"}, {"num": 171, "text": "Какой свет светофора загорается после зеленого?", "topic": "Дорожні знаки та розмітка", "options": ["Мигающий желтый.", "Зеленая стрелка.", "Только желтый.", "Только красный."], "correct": 2, "expl": "В Ірландії стандартна послідовність світлофора: зелений → жовтий → червоний → червоний і жовтий разом → знову зелений, без окремої фази мигання після зеленого.", "explSpecific": "Правильно — «Только желтый» одразу після зеленого. «Мигаюча жовта» і «зелена стрілка» не є частиною стандартної послідовності основного сигналу; «лише червоний» пропускає обов'язкову проміжну жовту фазу."}, {"num": 172, "text": "Что означает мигающая желтая стрелка, указывающая налево на светофоре?", "topic": "Дорожні знаки та розмітка", "options": ["Водитель может повернуть налево, но уступить дорогу транспорту на другой дороге.", "Водитель не должен двигаться на этом направлении.", "Водитель может продолжить двигаться перед транспортом на другой дороге.", "Водитель должен подождать, пока не загорится зеленый свет светофора."], "correct": 0, "expl": "Мигаюча жовта стрілка ліворуч на світлофорі дозволяє поворот, але без пріоритету — водій повинен спершу пропустити транспорт і пішоходів, для яких сигнал дозволяє рух.", "explSpecific": "Правильно — «Водитель может повернуть налево, но уступить дорогу транспорту на другой дороге». «Не рухатися в цьому напрямку» суперечить дозвільному, хоч і з умовою, сенсу мигання; «продовжити перед транспортом» і «чекати на зелений» неправильно описують саме поступливий характер мигаючої стрілки.", "img": "q172.png"}, {"num": 173, "text": "Когда водитель не должен продолжать движение, если на светофоре горит зеленый свет?", "topic": "Дорожні знаки та розмітка", "options": ["Когда транспорт стоит в ожидании поворота транспорта с дороги справа.", "Когда такой маневр небезопасен.", "Когда транспорт стоит в ожидании поворота транспорта с дороги слева.", "Когда встречный транспортный поток ожидает поворота налево."], "correct": 1, "expl": "Навіть маючи зелений сигнал, водій зобов'язаний утриматись від руху, якщо конкретний маневр небезпечний через дії інших учасників руху.", "explSpecific": "Правильно — «Когда такой маневр небезопасен». Варіанти про очікування повороту транспорту з дороги справа чи зліва чи очікування зустрічного потоку описують часткові приклади небезпечних ситуацій, тоді як загальне і точне правило — саме про небезпечність маневру як таку."}, {"num": 174, "text": "Какой свет светофора загорается после немигающего желтого.", "topic": "Дорожні знаки та розмітка", "options": ["Мигающий красный.", "Мигающий желтый.", "Только красный.", "Только зеленый."], "correct": 2, "expl": "Стандартна послідовність світлофора в Ірландії включає коротку фазу одночасного червоного й жовтого перед переходом на зелений, а фаза «лише червоний» настає одразу після звичайного жовтого.", "explSpecific": "Правильно — «Только красный» одразу після жовтого. «Мигаючий червоний» і «мигаюча жовта» не є частиною стандартної ірландської послідовності; «лише зелений» пропускає обов'язкову проміжну фазу."}, {"num": 175, "text": "Что означает мигающий желтый свет на переходе с автоматическим светофором?", "topic": "Дорожні знаки та розмітка", "options": ["Водитель выезжает на специальный участок ограничения скорости.", "Остановитесь и уступите дорогу переходам- продолжайте движение, если путь свободен.", "Преимущество движения транспортных средств.", "Впереди опасность. Водитель должен остановиться и дождаться, пока свет не перестанет мигать."], "correct": 1, "expl": "Мигаючий жовтий сигнал на пішохідному переході з автоматичним світлофором (пелікан) означає, що водій може їхати, лише пропустивши пішоходів, які ще не завершили перехід.", "explSpecific": "Правильно — «Остановитесь и уступите дорогу переходам — продолжайте движение, если путь свободен». «Спеціальна ділянка обмеження швидкості» і «перевага руху ТЗ» вигадують інший сенс мигання; «зупинитися і чекати, поки мигання не припиниться» надто категорично забороняє рух, хоча правило дозволяє їхати за вільного переходу."}, {"num": 176, "text": "Каков максимальный предел скорости автомобилей и мотоциклов на автомагистралях?", "topic": "Швидкісний режим", "options": ["120 км/ч.", "80 км/ч.", "100 км/ч.", "60 км/ч."], "correct": 0, "expl": "Стандартна максимальна швидкість на автомагістралі в Ірландії для легкових автомобілів і мотоциклів становить 120 км/год, якщо інше не вказано знаком.", "explSpecific": "Правильно — «120 км/ч». Це базове, встановлене законом обмеження для автомагістралей; менші цифри (60, 80, 100 км/ч) стосуються інших типів доріг чи інших категорій транспорту."}, {"num": 177, "text": "Если не указано иное, каков максимальный скоростной предел для автомобилей или мотоциклов на автострадах?", "topic": "Швидкісний режим", "options": ["60 км/ч.", "80 км/ч.", "100 км/ч.", "120 км/ч."], "correct": 2, "expl": "На автострадах (не автомагістралях) стандартна максимальна швидкість для легкових автомобілів і мотоциклів становить 100 км/год — менше, ніж на повноцінній автомагістралі.", "explSpecific": "Правильно — «100 км/ч». Автострада має нижчу межу, ніж автомагістраль (120 км/ч), тому саме ця цифра, а не 60, 80 чи 120 км/ч, відповідає стандартному обмеженню для автостради."}, {"num": 178, "text": "Если не указано иное, каков максимальный скоростной предел для автомобилей с автоприцепом на автострадах?", "topic": "Швидкісний режим", "options": ["60 км/ч.", "80 км/ч.", "120 км/ч.", "100 км/ч"], "correct": 1, "expl": "Для автомобіля з причепом на автостраді діє знижена межа швидкості порівняно зі звичайним легковим автомобілем без причепа, через довшу гальмівну дистанцію та складнішу керованість.", "explSpecific": "Правильно — «80 км/ч». Це знижене обмеження саме для транспорту з причепом; 100 і 120 км/ч стосуються звичайних автомобілів без причепа, а 60 км/ч — це надто занижена, не відповідна дійсному обмеженню цифра."}, {"num": 179, "text": "Если не указано другое, каков максимальный скоростной предел для автомобилей с автоприцепом на автомагистрали?", "topic": "Швидкісний режим", "options": ["100 км/ч", "80 км/ч", "120 км/ч", "90 км/ч"], "correct": 1, "expl": "На автомагістралі для транспорту з причепом діє знижена межа швидкості порівняно зі звичайним автомобілем без причепа.", "explSpecific": "Правильно — «80 км/ч» на автомагістралі для авто з причепом (та сама логіка зниженого обмеження, що й на автостраді). «100» і «120 км/ч» стосуються звичайних автомобілів без причепа; «90 км/ч» — не відповідна дійсному встановленому числу цифра."}, {"num": 180, "text": "Где разрешена стоянка автотранспорта?", "topic": "Паркування та зупинка", "options": ["На участках дороги со сплошной дороги со сплошной белой линией по центру.", "На тротуарах.", "На участках дорожных работ.", "В местах, в которых водитель не блокирует движение других участников дорожного движения и не препятствует их обзору сигналов светофора или дороги впереди."], "correct": 3, "expl": "Загальне правило стоянки в Ірландії: дозволено там, де автомобіль не створює перешкоду руху та не закриває огляд світлофорів чи дороги іншим учасникам, а не лише в спеціально виділених місцях.", "explSpecific": "Правильно — варіант про відсутність перешкоди руху та огляду сигналів. «На ділянці зі суцільною білою лінією по центру», «на тротуарах» і «на ділянках дорожніх робіт» — це якраз місця, де стоянка прямо заборонена, а не дозволена."}, {"num": 181, "text": "В пределах какого расстояния от пешеходного перехода стоянка автотранспорта запрещена?", "topic": "Паркування та зупинка", "options": ["5 метров.", "20 метров.", "10 метров.", "15 метров."], "correct": 3, "expl": "Стандартна заборонена для стоянки зона біля пішохідного переходу в Ірландії становить 15 метрів — це забезпечує видимість пішоходів для транспорту, що наближається.", "explSpecific": "Правильно — «15 метров». Інші числа (5, 10, 20 метрів) не відповідають встановленій нормі відстані для цього конкретного правила."}, {"num": 182, "text": "В пределах какого расстояния от перекрестка разрешена стоянка автотранспорта?", "topic": "Паркування та зупинка", "options": ["15 метров, или в четко обозначенных местах для стоянки.", "20 метров, или в четко обозначенных местах для стоянки.", "5 метров, или в четко обозначенных местах для стоянки.", "10 метров, или в четко обозначенных местах для стоянки."], "correct": 2, "expl": "Біля перехрестя стоянка дозволена, лише якщо вона на відстані щонайменше 5 метрів від перехрестя, або в спеціально позначеному для цього місці.", "explSpecific": "Правильно — «5 метров, или в четко обозначенных местах для стоянки». Інші відстані (10, 15, 20 метрів) не відповідають встановленій нормі для цього правила."}, {"num": 183, "text": "Когда водитель может парковать свой автомобиль на погрузочном пролёте?", "topic": "Паркування та зупинка", "options": ["Когда водитель является водителем грузового автомобиля и выполняет погрузку или разгрузку.", "Когда водитель является водителем грузового транспортного средства и не занимается погрузкой или разгрузкой.", "При наличии соответствующего пропуска.", "После проверки давления в шинах."], "correct": 0, "expl": "Погрузочний пролет (loading bay) призначений виключно для активного завантаження чи розвантаження вантажу, а не для звичайної стоянки будь-якого транспорту.", "explSpecific": "Правильно — стоянка дозволена лише вантажівці, яка саме зараз виконує завантаження чи розвантаження. «Вантажний ТЗ, що НЕ займається завантаженням» прямо суперечить призначенню зони; «за наявності перепустки» і «після перевірки тиску в шинах» вигадують умови, не пов'язані з цим правилом."}, {"num": 184, "text": "Разрешена ли стоянка автотранспорта у входа в частную собственность?", "topic": "Паркування та зупинка", "options": ["Да, в течение 1 часа, с 23.30 до 07.00.", "Да, в течение 1 часа, с 07.00 до 23.30.", "Да, с согласия владельца собственности.", "Да, вне рабочего времени."], "correct": 2, "expl": "Стоянка перед в'їздом до приватної власності обмежує доступ власника, тому дозволена лише за його прямою згодою, незалежно від часу доби чи тривалості.", "explSpecific": "Правильно — «Да, с согласия владельца собственности». Варіанти з конкретними часовими інтервалами і «поза робочим часом» вигадують умови, яких не існує — головна й єдина умова тут саме згода власника."}, {"num": 185, "text": "Когда разрешается стоянка на тротуаре?", "topic": "Паркування та зупинка", "options": ["Когда на пешеходной дорожке находится не более половины транспортного средства.", "Когда транспортные средства припаркованы с обеих сторон дороги.", "Стоянка на пешеходной дорожке запрещена.", "Когда хотя бы половина пешеходной дорожки остается свободной для пешеходов."], "correct": 2, "expl": "Стоянка на тротуарі (пішохідній доріжці) в Ірландії заборонена повністю, незалежно від того, скільки місця залишається вільним для пішоходів.", "explSpecific": "Правильно — «Стоянка на пешеходной дорожке запрещена» без винятків. Варіанти про «не більше половини ТЗ» чи «половина доріжки вільна» вигадують часткові дозволи, яких правило не передбачає."}, {"num": 186, "text": "Когда разрешается парковка вторым рядом?", "topic": "Паркування та зупинка", "options": ["В местах разметки в виде двойных желтых линий.", "В местах разметки в виде двойных белых линий.", "Всегда запрещена.", "На участках с твердой обочиной."], "correct": 2, "expl": "Паркування другим рядом (поряд з уже припаркованим транспортом, блокуючи смугу руху) заборонено завжди, без винятків за розміткою чи місцем.", "explSpecific": "Правильно — «Всегда запрещена». Варіанти про подвійні жовті чи білі лінії чи ділянки з твердою обочиною вигадують умови, за яких другий ряд начебто дозволений, хоча такого винятку не існує."}, {"num": 187, "text": "Когда разрешается стоянка на стоянке такси?", "topic": "Паркування та зупинка", "options": ["В ожидании посадки пассажиров из такси.", "Парковка на стоянке такси запрещена для всех, кроме водителей такси.", "В случае парковки менее, чем на 15 минут.", "Когда стояночное место свободно."], "correct": 1, "expl": "Зона стоянки таксі зарезервована виключно для таксі в будь-який момент, а не лише за певних обставин для інших водіїв.", "explSpecific": "Правильно — «Парковка на стоянке такси запрещена для всех, кроме водителей такси». «В очікуванні пасажирів з таксі» (для не-таксі) і «менше 15 хвилин» вигадують винятки для звичайних водіїв, яких не існує; «коли місце вільне» так само не скасовує заборону для не-таксі."}, {"num": 188, "text": "Когда разрешается стоянка на крутом изгибе дороги?", "topic": "Паркування та зупинка", "options": ["Когда водители, едущие сзади, видят припаркованный автомобиль.", "Когда на припаркованном транспортном средстве горят аварийные огни.", "Стоянка на крутом изгибе дороги запрещена.", "В случае стоянки на расстоянии не более 45 сантиметров от бордюра или края дороги."], "correct": 2, "expl": "На крутому вигині дороги стоянка заборонена завжди, оскільки припаркований автомобіль там значно знижує видимість і час реакції транспорту, що наближається.", "explSpecific": "Правильно — «Стоянка на крутом изгибе дороги запрещена» без винятків. Варіанти про видимість для транспорту ззаду, увімкнені аварійні вогні чи відстань до бордюру вигадують умови, за яких стоянка на вигині начебто дозволена, хоча такого винятку немає."}, {"num": 189, "text": "Когда разрешается стоянка на вершине холма?", "topic": "Паркування та зупинка", "options": ["Стоянка на вершине холма запрещена.", "Стоянка разрешена, если задействован ручной тормоз.", "Только при отсутствии транспорта на дороге.", "Если водитель повернул колеса в сторону бордюра."], "correct": 0, "expl": "На вершині пагорба стоянка заборонена завжди, оскільки транспорт, що наближається з протилежного боку, може дуже пізно помітити перешкоду через обмежену видимість за гребенем.", "explSpecific": "Правильно — «Стоянка на вершине холма запрещена» без винятків. «Дозволено при ввімкненому ручному гальмі», «лише за відсутності транспорту» і «якщо колеса повернуті до бордюру» вигадують умови, за яких стоянка на вершині пагорба начебто дозволена, хоча такого винятку немає."}, {"num": 190, "text": "Если тротуар не предусмотрен, где должны идти пешеходы?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Специальных правил не предусмотрено.", "По правой стороне дороги.", "По левой стороне дороги.", "На расстоянии 1 метра от обочины."], "correct": 1, "expl": "За відсутності тротуару пішоходи повинні йти по правій стороні дороги в Ірландії — назустріч транспортному потоку, що рухається лівою стороною, щоб бачити транспорт, який наближається.", "explSpecific": "Правильно — «По правой стороне дороги». «Відсутність спеціальних правил» ігнорує чітко встановлену норму; «ліва сторона» суперечила б принципу руху назустріч транспорту; «1 метр від узбіччя» — вигадана деталь."}, {"num": 191, "text": "Каковы действия пешеходов на узкой оживленной дороге?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Идти по одному (гуськом).", "Идти группами из не более трех человек.", "Иди больше двух в ряд.", "Идти по два в ряд."], "correct": 0, "expl": "На вузькій жвавій дорозі пішоходам безпечніше йти по одному (гуськом), а не групою чи в кілька рядів, щоб займати мінімум простору на проїзній частині.", "explSpecific": "Правильно — «Идти по одному (гуськом)». Групи з кількох людей чи рух у два ряди займають значно більше простору на вузькій дорозі, підвищуючи ризик для пішоходів."}, {"num": 192, "text": "В каких обстоятельствах пешеходам следует носить светоотражающую одежду в ночное время?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["В ночное время при ходьбе за пределами населенных пунктов.", "При ходьбе по два в ряд.", "При ходьбе в городских районах.", "Только во время дождя."], "correct": 0, "expl": "Світловідбивний одяг особливо важливий для пішоходів уночі поза межами населених пунктів, де освітлення відсутнє, а транспорт рухається швидше.", "explSpecific": "Правильно — «В ночное время при ходьбе за пределами населенных пунктов». Рух у два ряди сам по собі не вимагає світловідбивного одягу; міські райони зазвичай мають вуличне освітлення; прив'язка лише до дощу ігнорує головний фактор — темряву поза містом."}, {"num": 193, "text": "Какие участники дорожного движения должны соблюдать сигналы светофоров (включая пешеходные светофоры)?", "topic": "Дорожні знаки та розмітка", "options": ["Все участники дорожного движения.", "Только школьники.", "Только водители.", "Только пешеходы."], "correct": 0, "expl": "Сигнали світлофора (включно з пішохідними) є обов'язковими до виконання для кожного учасника дорожнього руху без винятків за категорією.", "explSpecific": "Правильно — «Все участники дорожного движения». «Тільки школярі», «тільки водії» чи «тільки пішоходи» звужують обов'язок до однієї категорії, тоді як правило стосується геть усіх — і водіїв, і пішоходів, і велосипедистів."}, {"num": 194, "text": "Что означает этот указательный щит на большом транспортном средстве?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Перевозка опасных грузов.", "Перевозка нависающего груза.", "Впереди медленный автомобиль.", "Выгрузка скота."], "correct": 1, "expl": "Два смугастих трикутники (один витягнутий, другий менший) на великогабаритному транспортному засобі позначають перевезення вантажу, що виступає (нависає) за габарити транспортного засобу.", "explSpecific": "Правильно — «Перевозка нависающего груза». Знаки для небезпечних вантажів чи вивантаження худоби мають зовсім інший вигляд; «попереду повільний автомобіль» не відповідає формі та призначенню цього знака.", "img": "q194.png"}, {"num": 195, "text": "Когда водитель должен использовать фары ближнего света?", "topic": "Погодні умови та видимість", "options": ["С 00:00 до 06:00.", "При видимости менее 300 метров.", "При видимости менее 200 метров.", "Сразу после заката и непосредственно перед рассветом."], "correct": 3, "expl": "Фари ближнього світла обов'язково вмикають одразу після заходу сонця і перед світанком — саме в цей проміжок природного освітлення вже недостатньо для безпечного руху.", "explSpecific": "Правильно — «Сразу после заката и непосредственно перед рассветом». Фіксовані години доби (00:00-06:00) не враховують сезонні зміни тривалості дня; прив'язка до конкретної видимості в метрах стосується густого туману, а не звичайних сутінків."}, {"num": 196, "text": "Какой свет следует использовать водителю в сумеречное время?", "topic": "Погодні умови та видимість", "options": ["Только дневные ходовые огни ДХО.", "Противотуманные фары.", "Фары ближнего света.", "Дальний свет."], "correct": 2, "expl": "У сутінках (проміжний час між днем і темрявою) правильний вибір освітлення — фари ближнього світла, які забезпечують достатню видимість, не засліплюючи інших.", "explSpecific": "Правильно — «Фары ближнего света». Лише денні ходові вогні недостатньо яскраві для сутінок; протитуманні фари призначені для туману; дальнє світло в цей час доби ще не обов'язкове й може завадити зустрічним."}, {"num": 197, "text": "Когда водителям следует останавливаться на автоматическом железнодорожном переезде со шлагбаумом и мигающими красными огнями?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Осторожно остановитесь, когда загорится желтый свет или когда красный свет начнет мигать.", "Когда шлагбаум полностью поднят.", "Когда красный и желтый свет перестанут мигать.", "Когда нет видимых огней."], "correct": 0, "expl": "На автоматичному залізничному переїзді зі шлагбаумом сигнали з'являються послідовно: спершу жовте світло, потім мигаюче червоне — зупинятися потрібно вже на цих ранніх стадіях, не чекаючи опускання шлагбаума.", "explSpecific": "Правильно — «Осторожно остановитесь, когда загорится желтый свет или когда красный свет начнет мигать». Очікування повністю піднятого шлагбаума чи припинення мигання — це вже сигнали ПІСЛЯ проїзду поїзда; «коли немає видимих вогнів» взагалі не є ознакою небезпеки."}, {"num": 198, "text": "Для чего предназначены участки обеспечения принудительного снижения скорости транспорта?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Чтобы замедлить движение автотранспорта в непосредственной близости.", "Чтобы отдать приоритет тяжелым транспортным средствам.", "Чтобы предупредить водителей о затоплении дороги впереди.", "Чтобы предупредить водителя об увеличении скоростного предела впереди."], "correct": 0, "expl": "Ділянки примусового зниження швидкості (лежачі поліцейські, звуження) призначені для того, щоб сповільнити рух транспорту в безпосередній близькості, зазвичай біля шкіл, житлових зон чи небезпечних перехресть.", "explSpecific": "Правильно — «Чтобы замедлить движение автотранспорта в непосредственной близости». Пріоритет важким транспортним засобам, попередження про затоплення дороги чи про підвищення швидкісного ліміту — не є призначенням таких ділянок."}, {"num": 199, "text": "Когда разрешается езда с прицепом без номерного знака по дороге общественного пользования?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["При буксировке сельскохозяйственным трактором.", "Когда задний откидной борт снят.", "При перевозке груза, который нависает над прицепом.", "Никогда номерной знак должен использоваться всегда."], "correct": 3, "expl": "Причіп на дорозі загального користування завжди повинен мати номерний знак — винятків не передбачено.", "explSpecific": "Правильно — «Никогда номерной знак должен использоваться всегда». Буксирування трактором, знятий задній борт чи перевезення вантажу, що нависає, не звільняють від обов'язкової наявності номерного знака."}, {"num": 200, "text": "Когда водителю разрешается пропускать другое транспортное средство с левой стороны?", "topic": "Обгін та зміна смуги руху", "options": ["Когда для этого маневра достаточно пространства.", "Когда автомобиль впереди сигнализирует о повороте вправо или на полосе движения с низкой скоростью.", "Водитель никогда не должен обгонять слева.", "Когда водитель не может проехать по правой стороне из-за встречного движения."], "correct": 1, "expl": "Обгін зліва — виняток із загального правила обгону справа, дозволений лише за конкретних обставин: коли транспорт попереду сигналізує поворот праворуч або рухається смугою повільного руху.", "explSpecific": "Правильно — «Когда автомобиль впереди сигнализирует о повороте вправо или на полосе движения с низкой скоростью». «Коли достатньо простору» — надто загальна умова; «ніколи не можна обганяти зліва» суперечить наявним у правилах винятками."}, {"num": 201, "text": "Кому разрешается ехать по велосипедной дорожке со сплошной белой линией по левой стороне дороги?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Водителям, когда она не используется велосипедистами.", "Водителям, при обгоне автомобиля, поворачивающего направо.", "Велосипедистам и мотоциклистам.", "Велосипедистам и пользователям механических инвалидных колясок."], "correct": 3, "expl": "Велосипедна доріжка з суцільною білою лінією — обов'язкова для велосипедистів і користувачів механічних інвалідних візків, і водіям заходити на неї заборонено.", "explSpecific": "Правильно — «Велосипедистам и пользователям механических инвалидных колясок». Водіям в'їзд заборонений завжди, незалежно від зайнятості доріжки; мотоциклісти не входять до переліку дозволених користувачів."}, {"num": 202, "text": "Каким транспортным средствам разрешается ехать по велосипедной дорожке с прерывистой белой линией?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Велосипедистам и пользователям механических инвалидных колясок.", "Велосипедистам и мотоциклистам.", "Автобусам и велосипедистам.", "Велосипедистам и такси."], "correct": 0, "expl": "Велосипедна доріжка з переривчастою білою лінією менш строго відокремлена від дороги, але дозволені користувачі ті самі — велосипедисти й користувачі механічних інвалідних візків.", "explSpecific": "Правильно — «Велосипедистам и пользователям механических инвалидных колясок». Мотоцикли, автобуси й таксі не входять до переліку дозволених користувачів велосипедної доріжки незалежно від типу розмітки."}, {"num": 203, "text": "Какие другие участники дорожного движения, кроме велосипедистов и пользователей механических инвалидных колясок, могут использовать свободные велосипедные дорожки со сплошной белой линией?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Только автобусы и такси.", "Все водители транспортных средств могут временно ее использовать.", "Только верховые лошади и такси.", "Только водители мопедов и мотоциклов."], "correct": 1, "expl": "Якщо велосипедна доріжка з суцільною лінією вільна (немає велосипедистів), інші водії можуть тимчасово нею скористатися, наприклад, для об'їзду перешкоди.", "explSpecific": "Правильно — «Все водители транспортных средств могут временно ее использовать». Обмеження лише автобусами й таксі чи лише кіньми й таксі — вигадані переліки; лише мопедами й мотоциклами так само звужує реальне правило."}, {"num": 204, "text": "Каковы действия водителя на железнодорожном переезде с автоматическими воротами?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Проехать полпути и закрыть первые ворота, прежде чем открыть вторые.", "Открыть ворота с обеих сторон после проезда первых, остановиться и закрыть их.", "Позвонить на ближайшую железнодорожную станцию, прежде чем открыть ворота.", "Открыть ворота с обеих сторон, прежде чем пересечь переезд."], "correct": 3, "expl": "На залізничному переїзді з ручними воротами водій повинен відкрити ОБИДВІ стулки воріт заздалегідь, перш ніж виїжджати на колії, щоб не зупинятися посередині переїзду.", "explSpecific": "Правильно — «Открыть ворота с обеих сторон, прежде чем пересечь переезд». «Проїхати половину шляху і закрити перші ворота» небезпечно залишає автомобіль на коліях; дзвінок на станцію не замінює фізичного відкриття воріт."}, {"num": 205, "text": "Какими сигнальными огнями обозначается пешеходный переход типа \"зебра\"?", "topic": "Дорожні знаки та розмітка", "options": ["Желтые светофоры.", "Постоянно горящие красные светофоры.", "Мигающие красные светофоры.", "Постоянно горящие желтые светофоры."], "correct": 0, "expl": "Пішохідний перехід типу «зебра» в Ірландії традиційно позначається парою жовтих мигаючих ліхтарів (Belisha beacons) з обох боків дороги, а не звичайним трисекційним світлофором.", "explSpecific": "Правильно — «Желтые светофоры» (мигаючі жовті кулі-ліхтарі). «Постійно горящі червоні/жовті» і «мигаючі червоні» описують режими роботи звичайного регульованого світлофора на переході з автоматикою (пелікан/пуффін), а не класичну зебру."}, {"num": 206, "text": "Что означают желтые мигающие стрелки на перекрестке?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Тупик в указанном направлении.", "Запрещено движение в указанном направлении.", "Оперативно проезжайте через перекресток, чтобы избежать задержки.", "Водителям следует двигаться в указанном направлении, если это безопасно."], "correct": 3, "expl": "Жовті мигаючі стрілки на перехресті вказують дозволений напрямок руху, яким водії можуть скористатися, якщо це безпечно.", "explSpecific": "Правильно — «Водителям следует двигаться в указанном направлении, если это безопасно». Твердження про глухий кут, повну заборону руху чи вимогу проїжджати оперативно, щоб уникнути затримки, — не відповідають призначенню мигаючих стрілок."}, {"num": 207, "text": "Что означают временные светофоры на участках проведения дорожных работ?", "topic": "Дорожні знаки та розмітка", "options": ["Водитель должен соблюдать таких светофоров только при встречном движении.", "Водителю не нужно соблюдать эти сигналы, если колонна транспорта идет в том же направлении.", "Водитель должен соблюдать сигналы только когда рабочие работают на данном участке.", "Водитель всегда должен соблюдать сигналы таких светофоров."], "correct": 3, "expl": "Тимчасові світлофори на ділянці дорожніх робіт мають ту саму юридичну силу, що й постійні, і мусять виконуватися завжди, незалежно від наявності робітників чи напрямку руху.", "explSpecific": "Правильно — «Водитель всегда должен соблюдать сигналы такого светофора». Варіанти про виняток при зустрічному русі, при русі колоною в тому ж напрямку чи лише коли працюють робітники вигадують послаблення правила, якого не існує — тимчасовий світлофор діє завжди, поки він увімкнений."}, {"num": 208, "text": "Когда временные ограничения скорости применяются на участках дорожных работ?", "topic": "Швидкісний режим", "options": ["Только когда рабочие работают на данном участке.", "Только в рабочие часы.", "В период выполнения дорожных работ.", "Только в случае встречного транспортного потока."], "correct": 2, "expl": "Тимчасові обмеження швидкості на ділянці дорожніх робіт діють протягом усього періоду виконання робіт, а не лише коли робітники фізично присутні чи в певні години.", "explSpecific": "Правильно — «В период выполнения дорожных работ». «Тільки коли робітники працюють» чи «тільки в робочі години» невиправдано звужують дію обмеження; прив'язка лише до зустрічного потоку не має стосунку до причини обмеження."}, {"num": 209, "text": "Как правильно действовать в этой ситуации?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Ускориться, чтобы быстро пропустить детей.", "Внимательно следить за детьми и приготовиться своевременно остановиться.", "Продолжить движение ближе к левой стороне и подать звуковой сигнал.", "Продолжить ехать с той же скоростью."], "correct": 1, "expl": "Діти біля проїжджої частини непередбачувані і можуть раптово вийти на дорогу, тому водій повинен уважно стежити за ними і бути готовим вчасно зупинитися.", "explSpecific": "Правильно — «Внимательно следить за детьми и приготовиться своевременно остановиться». Прискорення, щоб швидше проїхати повз, рух ближче до лівого краю зі звуковим сигналом чи збереження тієї самої швидкості — небезпечні дії біля дітей поруч з дорогою.", "img": "q209.png"}, {"num": 210, "text": "Приближающийся водитель заметил, что мальчик на детском велосипеде попрощался со своим другом. Как следует поступить водителю в этой ситуации?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Быть готовым к тому, что мальчик тронется в любой момент.", "Замедлиться и подать мальчику сигнал о пересечении дороги.", "Продолжить движение, пока мальчик находится на тротуаре", "Остановиться и дождаться, пока мальчик не тронется."], "correct": 0, "expl": "Побачивши дитину на велосипеді біля дороги, яка щойно попрощалася з другом, водій повинен бути готовим, що вона рушить у будь-яку мить, оскільки поведінка дітей непередбачувана.", "explSpecific": "Правильно — «Быть готовым к тому, что мальчик тронется в любой момент». Подача сигналу про перехід чи очікування, поки хлопчик рушить, — пасивні реакції; продовження руху «поки хлопчик на тротуарі» недооцінює швидкість, з якою дитина може виїхати."}, {"num": 211, "text": "Каковы правильные действия водителя автомобиля в этой ситуации?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Водитель может осторожно продолжить движение.", "Замедлиться и подать мотоциклисту сигнал о пересечении дороги.", "Водитель должен уступить движение транспорту слева.", "Водитель должен ехать с первой стороны, чтобы оставить зазор для проезда мотоциклиста."], "correct": 0, "expl": "У цій ситуації водій автомобіля має пріоритет і може обережно продовжити рух, залишаючись уважним до мотоцикліста.", "explSpecific": "Правильно — «Водитель может осторожно продолжить движение». Подача сигналу мотоциклісту про перетин дороги описує іншу ситуацію; поступливість транспорту зліва чи спеціальне зміщення для мотоцикліста не відповідають наявному тут пріоритету водія.", "img": "q211.png"}, {"num": 212, "text": "Как водитель должен поступить в этой ситуации?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Водитель может повернуть направо до велосипедиста.", "Водитель должен пропустить мотоциклиста.", "Водитель должен пропустить велосипедиста.", "Водитель должен остановиться и уступить дорогу другим участникам дорожного движения."], "correct": 2, "expl": "На перехресті, де велосипедист перетинає шлях водія, водій повинен пропустити велосипедиста, перш ніж продовжити рух.", "explSpecific": "Правильно — «Водитель должен пропустить велосипедиста». На зображенні саме велосипедист перетинає траєкторію водія; мотоцикліста в цій ситуації немає, а зупинка й пропуск усіх учасників або поворот праворуч до велосипедиста — небезпечні чи недоречні дії.", "img": "q212.png"}, {"num": 213, "text": "К чему водитель должен быть готов в этой ситуации?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Встречное транспортное средство может повернуть в вашу сторону.", "После того, как вы проедете, мяч может лопнуть.", "Ребенок может вернуться назад, чтобы забрать мяч дороги.", "Мяч может повредить ваш автомобиль."], "correct": 2, "expl": "Коли діти грають з м'ячем біля дороги, головна прихована небезпека — не сам м'яч, а дитина, яка може раптово вибігти на проїжджу частину слідом за ним.", "explSpecific": "Правильно — «Ребенок может вернуться назад, чтобы забрать мяч дороги». Загроза від зустрічного авто чи можливість пошкодження машини м'ячем — другорядні й малоймовірні сценарії порівняно з ризиком для дитини.", "img": "q213.png"}, {"num": 214, "text": "Что должен делать водитель в данной ситуации на подъезде к пешеходному переходу?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Сохранять скорость, поскольку пешеходы еще не ступили на переход.", "Продолжить движение с той же скоростью, поскольку пешеходы должны подождать, пока не проедет автомобиль.", "Снизить скорость и приготовиться остановиться.", "Подать звуковой сигнал, чтобы привлечь внимание к своему автомобилю и продолжить движение с той же скоростью."], "correct": 2, "expl": "Наближаючись до пішохідного переходу, де є пішоходи, водій повинен знизити швидкість і бути готовим зупинитися, а не покладатися на те, що пішоходи почекають.", "explSpecific": "Правильно — «Снизить скорость и приготовиться остановиться». Збереження швидкості в очікуванні, що пішоходи почекають, чи звуковий сигнал із продовженням руху — недостатньо обережні реакції.", "img": "q214.png"}, {"num": 215, "text": "Как водитель должен поступить в этой ситуации?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["При въезде на кольцевую развязку, водитель имеет преимущество движения.", "Водитель может продолжать движение по кольцевой развязке перед желтой машиной.", "Водитель должен дождаться, пока желтый автомобиль не остановится.", "Водитель должен уступить дорогу желтому автомобилю на кольцевой развязке."], "correct": 3, "expl": "В'їжджаючи на кільцеву розв'язку, водій повинен поступитися дорогою транспорту, який вже рухається по ній чи наближається справа, — у цьому випадку жовтому автомобілю.", "explSpecific": "Правильно — «Водитель должен уступить дорогу желтому автомобилю на кольцевой развязке». Твердження про автоматичну перевагу водія при в'їзді, можливість проїхати перед жовтою машиною чи очікування її повної зупинки — суперечать базовому правилу пріоритету на кільцевих розв'язках.", "img": "q215.png"}, {"num": 216, "text": "Как водитель должен поступить в этой ситуации?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Водитель должен пропустить мотоциклиста.", "Поворот направо запрещен запрещен водителю автомобиля.", "Водитель автомобиля может продолжить движение первым.", "Водитель автомобиля должен пропустить автобус."], "correct": 0, "expl": "На перехресті з рівнозначними дорогами пріоритет має транспорт, що наближається справа, — у цій ситуації це мотоцикліст, якому водій повинен поступитися.", "explSpecific": "Правильно — «Водитель должен пропустить мотоциклиста». Заборона повороту праворуч тут не застосовна; продовження руху першим чи поступливість автобусу не відповідають правилу пріоритету праворуч на рівнозначному перехресті.", "img": "q216.png"}, {"num": 217, "text": "Как водитель должен поступить в этой ситуации?", "topic": "Паркування та зупинка", "options": ["Водитель должен пропустить красный автомобиль.", "Водитель должен пропустить синий автомобиль.", "Водитель может повернуть перед двумя другими автомобилями.", "Водитель должен остановиться и пропустить все остальные автомобили."], "correct": 2, "expl": "На перехресті з рівнозначними дорогами, коли обидва інші автомобілі перебувають на достатній відстані і не створюють завади, водій може виконати поворот, не чекаючи на них.", "explSpecific": "Правильно — «Водитель может повернуть перед двумя другими автомобилями». Обов'язок пропустити червоний чи синій автомобіль окремо, або зупинитися й пропустити взагалі всіх, не відповідає ситуації, де достатньо часу й простору для безпечного повороту.", "img": "q217.png"}, {"num": 218, "text": "Чему водитель должен уделить внимание в этой ситуации?", "topic": "Паркування та зупинка", "options": ["Между припаркованными транспортными средствами могут быть мусорные баки.", "Пешеходы могут путешествовать автостопом.", "Пешеходы могут проходить между припаркованными автомобилями.", "Припаркованные автомобили могут иметь прицепы."], "correct": 2, "expl": "Проїжджаючи повз ряд припаркованих автомобілів, водій повинен пам'ятати, що пішоходи можуть несподівано вийти на проїзну частину саме з проміжків між машинами.", "explSpecific": "Правильно — «Пешеходы могут проходить между припаркованными автомобилями». Сміттєві баки, автостоп чи причепи на припаркованих авто — вигадані чи малоймовірні деталі порівняно з реальним ризиком пішоходів між машинами.", "img": "q218.png"}, {"num": 219, "text": "Каковы действия водителя, если на краю проезжей части играют дети?", "topic": "Обгін та зміна смуги руху", "options": ["Снизить скорость, осторожно продолжать движение и быть готовым к торможению.", "Ускориться и двигаться по правой стороне дороги, чтобы объехать детей.", "Подать предупреждающий сигнал и проехать с той же скоростью.", "Сохранять ту же скорость, поскольку в этот момент дети могут отчетливо видеть автомобиль, движущийся по встречной полосе."], "correct": 0, "expl": "Побачивши дітей, що грають біля краю проїзної частини, водій повинен знизити швидкість і бути готовим будь-якої миті зупинитися, оскільки поведінка дітей непередбачувана.", "explSpecific": "Правильно — «Снизить скорость, осторожно продолжать движение и быть готовым к торможению». Прискорення чи об'їзд праворуч, сигнал з тією ж швидкістю — усе це недостатньо обережні реакції на дітей біля дороги.", "img": "q219.png"}, {"num": 220, "text": "Как водитель должен поступить в этой ситуации?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Водитель должен пропустить другие транспортные средства.", "Велосипедист имеет преимущественное право движения.", "Водитель должен дождаться, пока фургон не пересечет перекресток.", "Водитель должен осторожно продолжить движение вперед."], "correct": 3, "expl": "Маючи перевагу проїзду на перехресті (позначену знаком головної дороги) і чистий шлях попереду, водій може обережно продовжити рух прямо.", "explSpecific": "Правильно — «Водитель должен осторожно продолжить движение вперед». Пропуск інших транспортних засобів чи очікування, поки фургон перетне перехрестя, не потрібні, коли водій має перевагу проїзду; велосипедист на зображенні не перебуває на шляху водія.", "img": "q220.png"}, {"num": 221, "text": "Как водитель должен поступить в этой ситуации?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Поворот направо запрещен водителю автомобиля.", "Водитель должен повернуть налево.", "Водитель должен пропустить оранжевый автомобиль.", "Водитель может повернуть направо."], "correct": 3, "expl": "Виїжджаючи праворуч з другорядної дороги, водій повинен оцінити відстань і швидкість транспорту на головній дорозі — за наявності достатнього проміжку маневр дозволений.", "explSpecific": "Правильно — «Водитель может повернуть направо». Твердження про заборону повороту праворуч чи обов'язковий поворот ліворуч не відповідають ситуації з вільним проміжком; «повинен пропустити помаранчевий автомобіль» описує ситуацію, де відстань насправді недостатня, що тут не так.", "img": "q221.png"}, {"num": 222, "text": "Как водитель должен поступить в этой ситуации?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Водитель должен пропустить красный автомобиль.", "Водитель может продолжить движение первым.", "Поворот направо запрещен водителю автомобиля.", "Водитель должен пропустить синий грузовик."], "correct": 3, "expl": "На перехресті, де траєкторія руху водія перетинає смугу зустрічного великогабаритного транспорту, водій повинен пропустити синю вантажівку, що має перевагу проїзду.", "explSpecific": "Правильно — «Водитель должен пропустить синий грузовик». Пропуск червоного автомобіля, продовження руху першим чи заборона повороту праворуч не відповідають зображеній ситуації, де саме вантажівка рухається по смузі, яку перетинає водій.", "img": "q222.png"}, {"num": 223, "text": "Чего водителю следует остерегаться в этой ситуации?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Перед тем как отъехать, водитель автобуса всегда подает сигнал.", "Транспорта с улицы слева.", "Людей, переходящих улицу в задней части автобуса.", "Автобус может начать разворот."], "correct": 2, "expl": "Зупинений автобус приховує огляд, тому найбільша небезпека — пішоходи, які можуть несподівано вийти на проїжджу частину з-за задньої частини автобуса.", "explSpecific": "Правильно — «Людей, переходящих улицу в задней части автобуса». Твердження про сигнал водія автобуса перед від'їздом, транспорт зліва чи можливий розворот автобуса не є основною небезпекою в цій ситуації.", "img": "q223.png"}, {"num": 224, "text": "Серебристый автомобиль совершает обгон припаркованного красного автомобиля, что должен делать водитель в этой ситуации?", "topic": "Обгін та зміна смуги руху", "options": ["Водитель должен продолжить движение, если мяч не дарится об автомобиль.", "Водитель должен продолжить движение с той же скоростью.", "Водитель должен ехать ближе к красному автомобилю.", "Значительно снизить скорость и приготовиться остановиться."], "correct": 3, "expl": "Коли інший автомобіль обганяє припаркований транспорт попереду вас, ви маєте значно знизити швидкість і бути готовим зупинитися, оскільки обгін попереду створює непередбачувану ситуацію.", "explSpecific": "Правильно — «Значительно снизить скорость и приготовиться остановиться». Продовження руху з тією ж швидкістю ігнорує ризик, створений маневром обгону попереду; умова про м'яч, що вдариться об автомобіль, — вигаданий критерій.", "img": "q224.png"}, {"num": 225, "text": "Чему водителю следует остерегаться в этой ситуации?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Трамвай может отъехать без предупреждения.", "У пешеходов всегда преимущественное право прохода перед транспортом.", "Нет никакой опасности, поскольку трамвай стоит на рельсах.", "Пешеход может покинуть островок безопасности, не обратив внимание на движущийся транспорт."], "correct": 3, "expl": "Пішохід, що стоїть на острівці безпеки біля трамвайних колій, може раптово зійти з нього, не помітивши транспорт, що наближається, — це прихована небезпека ситуації.", "explSpecific": "Правильно — «Пешеход может покинуть островок безопасности, не обратив внимание на движущийся транспорт». Трамвай, що рушає без попередження, — менш імовірна тут небезпека; твердження про абсолютний пріоритет пішоходів — перебільшення.", "img": "q225.png"}, {"num": 226, "text": "Водитель следует за этими двумя транспортными средствами и намеревается совершить обгон. Что должен учесть водитель, прежде чем совершить обгон?", "topic": "Обгін та зміна смуги руху", "options": ["Водитель серебристого автомобиля может решить повернуть направо.", "Водитель должен обогнать сразу оба транспортных средства.", "Поле зрения водителя недостаточно хорошее для безопасного обгона.", "Разметка проезжей части запрещает обгон на этом участке."], "correct": 2, "expl": "Перш ніж обганяти два транспортні засоби одразу, водій повинен переконатися, що має достатній огляд дороги попереду для безпечного завершення маневру.", "explSpecific": "Правильно — «Поле зрения водителя недостаточно хорошее для безопасного обгона». Намір іншого автомобіля повернути праворуч чи обов'язок обганяти обидва одразу — вигадані міркування.", "img": "q226.png"}, {"num": 227, "text": "О чем должен знать водитель, приближаясь к транспортному средству, которое пытается припарковаться?", "topic": "Паркування та зупинка", "options": ["Что припаркованное транспортное средство может выехать на проезжую часть без предупреждения.", "Водителю, возможно, придется остановиться и помочь водителю припарковать автомобиль.", "В месте парковки автомобиля может находиться проезжая часть.", "Транспортное средство может парковаться в зоне, предназначенной для погрузки."], "correct": 0, "expl": "Наближаючись до транспорту, який намагається припаркуватися, водій повинен бути готовим, що той може несподівано виїхати назад на проїзну частину без попередження.", "explSpecific": "Правильно — «Что припаркованное транспортное средство может выехать на проезжую часть без предупреждения». Обов'язок зупинитися й допомогти з паркуванням чи припущення про зону навантаження — вигадані реакції водія, що просто проїжджає повз.", "img": "q227.png"}, {"num": 228, "text": "Что должен учитывать водитель, следуя за автобусом по гололеду?", "topic": "Погодні умови та видимість", "options": ["Необходим более короткий тормозной путь.", "Необходим такой же тормозной путь, что и в условиях сухой дороги.", "Необходим такой же тормозной путь, что и в условиях влажной дороги.", "Необходим более длинный тормозной путь."], "correct": 3, "expl": "На ожеледиці зчеплення шин з дорогою мінімальне, тому за автобусом чи будь-яким транспортом слід тримати значно більшу дистанцію, ніж зазвичай — гальмівний шлях суттєво подовжується.", "explSpecific": "Правильно — «Необходим более длинный тормозной путь». Твердження про коротший чи такий самий шлях, як на сухій чи вологій дорозі, применшують реальну небезпеку ожеледиці, яка є найслизькішою з цих умов.", "img": "q228.png"}, {"num": 229, "text": "Что должен сделать водитель серебряного автомобиля, прежде чем повернуть налево?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Обогнать велосипедиста слева и завершить поворот.", "Увеличьте скорость, чтобы иметь возможность завершить поворот налево перед велосипедистом.", "Позвольте проехать велосипедисту, направляющемуся прямо.", "Подать звуковой сигнал, чтобы предупредить велосипедиста о присутствии автомобиля."], "correct": 2, "expl": "Повертаючи ліворуч, водій повинен пропустити велосипедиста, який продовжує рух прямо, оскільки той має пріоритет над транспортом, що повертає й перетинає його шлях.", "explSpecific": "Правильно — «Позвольте проехать велосипедисту, направляющемуся прямо». Обгін велосипедиста зліва перед поворотом чи прискорення, щоб завершити поворот раніше за нього, — небезпечні маневри, що порушують його пріоритет.", "img": "q229.png"}, {"num": 230, "text": "Какой свет фар следует использовать водителю в густом тумане?", "topic": "Погодні умови та видимість", "options": ["Передние и задние противотуманные фары, а также сигнальные огни.", "Передние и задние противотуманные фары вместе с фарами дальнего света.", "Передние и задние противотуманные фары вместе с фарами ближнего света.", "Передние и задние противотуманные фары вместе с боковыми фарами."], "correct": 2, "expl": "У густому тумані оптимальне освітлення — передні й задні протитуманні фари в поєднанні з фарами ближнього світла, які освітлюють дорогу, не створюючи засліплюючого відбиття від туману.", "explSpecific": "Правильно — «...вместе с фарами ближнего света». Дальнє світло у тумані відбивається від крапель вологи назад до водія; сигнальні чи бокові вогні недостатні для освітлення дороги.", "img": "q230.png"}, {"num": 231, "text": "Чего водителю следует остерегаться в этой ситуации?", "topic": "Паркування та зупинка", "options": ["На левой стороне дороги запрещается парковать транспортные средства.", "Одно из припаркованных транспортных средств может вернуться на путь водителя.", "Пешеход может внезапно перейти дорогу перед автомобилем.", "У пешеходов всегда преимущественное право перейти дорогу."], "correct": 2, "expl": "Проїжджаючи повз ряд припаркованих автомобілів, водій повинен остерігатися пішохода, що може раптово вийти на проїзну частину прямо перед автомобілем.", "explSpecific": "Правильно — «Пешеход может внезапно перейти дорогу перед автомобилем». Заборона стоянки зліва чи повернення одного з припаркованих авто на шлях водія — менш імовірні чи вигадані деталі порівняно з реальним ризиком пішохода.", "img": "q231.png"}, {"num": 232, "text": "Как водитель должен поступить в этой ситуации?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Водитель должен поддерживать текущую скорость и уменьшить расстояние от серебряного автомобиля.", "Водитель может обогнать машину и девушку, так как дорога размечена пунктирной белой линией.", "Снизить скорость и быть готовым притормозить, поскольку девушка может внезапно начать переходить дорогу.", "Водитель должен быть готов к тому, чтобы транспортное средство впереди увеличит скорость."], "correct": 2, "expl": "У ситуаціях, коли поруч із дорогою перебуває пішохід, який може непередбачувано вийти на проїжджу частину, головне правило — завчасно знизити швидкість і бути готовим зупинитися, а не покладатися на розмітку чи сподіватися, що пішохід не вийде.", "explSpecific": "Правильно — «Снизить скорость и быть готовым притормозить». Підтримання швидкості й скорочення дистанції до автомобіля попереду ігнорує ризик з боку дівчини; посилання на переривчасту лінію як дозвіл обгону підмінює тему; очікування, що інший автомобіль прискориться, не є розумною стратегією водія.", "img": "q232.png"}, {"num": 233, "text": "Как водителю следует поступить?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Водитель должен позволить встречному велосипедисту повернуть первым.", "Водитель должен пропустить желтый автомобиль.", "Водитель должен остановиться и уступить дорогу всему транспорту.", "Водитель может повернуть налево первым."], "correct": 1, "expl": "На цьому перехресті жовтий автомобіль має перевагу проїзду, тому водій повинен його пропустити, перш ніж повертати ліворуч.", "explSpecific": "Правильно — «Водитель должен пропустить желтый автомобиль». Дозвіл зустрічному велосипедисту повернути першим, зупинка й пропуск усього транспорту чи поворот ліворуч першим — не відповідають зображеній ситуації, де саме жовтий автомобіль має пріоритет.", "img": "q233.png"}, {"num": 234, "text": "Какой из автомобилей припаркован неправильно (если таковой имеется)?", "topic": "Паркування та зупинка", "options": ["Красный автомобиль.", "Ни один из автомобилей.", "Зеленый автомобиль.", "Оба автомобиля."], "correct": 3, "expl": "Обидва автомобілі на зображенні припарковані занадто близько до пішохідного переходу типу «зебра», що заборонено правилами.", "explSpecific": "Правильно — «Оба автомобиля». Виділення лише одного з двох (червоного чи зеленого) не відповідає ситуації, де обидва порушують правило відстані від переходу.", "img": "q234.png"}, {"num": 235, "text": "Чего водителю следует остерегаться в этой ситуации?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Велосипедист может выехать на проезжую часть, не обратив внимания на движение транспорта.", "Велосипедист остановится в конце велосипедной дорожки, чтобы пропустить движущийся транспорт.", "Велосипедист останется на велосипедной дорожке.", "Водитель должен переместиться на левую (ближнюю) сторону, если велосипедист выедет."], "correct": 0, "expl": "Наближаючись до кінця велосипедної доріжки, водій повинен бути готовим, що велосипедист може виїхати на проїзну частину, не звернувши уваги на транспортний потік.", "explSpecific": "Правильно — «Велосипедист может выехать на проезжую часть, не обратив внимания на движение транспорта». Впевненість, що велосипедист зупиниться чи залишиться на доріжці, недооцінює реальний ризик.", "img": "q235.png"}, {"num": 236, "text": "Водитель хочет съехать с проезжей части и повернуть направо на дорогу. В то же самое время велосипедист приближается справа, и пешеход хочет перейти дорогу. Кто должен подождать?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Пешеход и велосипедист должны подождать.", "Водитель должен подождать.", "Велосипедист должен подождать.", "Пешеход должен подождать."], "correct": 1, "expl": "Коли водій хоче з'їхати з проїзної частини й повернути праворуч, а одночасно велосипедист наближається справа і пішохід хоче перейти дорогу, саме водій має зачекати, пропустивши обох.", "explSpecific": "Правильно — «Водитель должен подождать». Твердження, що чекати повинні пішохід і/чи велосипедист, суперечить їхньому пріоритету над транспортом, що маневрує.", "img": "q236.png"}, {"num": 237, "text": "Какие действия должен предпринять водитель?", "topic": "Дорожні знаки та розмітка", "options": ["Продолжить движение перед автобусом.", "Подать сигнал автобусу, чтобы продолжить движение.", "Продолжить движение перед велосипедистом.", "Остановиться перед Стоп-линией / на Стоп-линии."], "correct": 3, "expl": "Ситуація на дорозі (наприклад, автобус чи велосипедист попереду) визначає, коли водій зобов'язаний зупинитися перед стоп-лінією замість продовження руху.", "explSpecific": "Правильно — «Остановиться перед Стоп-линией / на ней». «Продовжити перед автобусом/велосипедистом» і «подати сигнал автобусу продовжити» суперечать обов'язку водія зупинитися і пропустити транспорт, що має пріоритет у цій ситуації.", "img": "q237.png"}, {"num": 238, "text": "Как водитель должен поступить, следуя за этим транспортным средством?", "topic": "Швидкісний режим", "options": ["Обогнать автомобиль перед вами.", "Медленно обогнать автомобиль, приблизившись к бордюру слева.", "Двигаться как можно ближе к автомобилю.", "Снизить скорость и быть готовым остановиться, при необходимости."], "correct": 3, "expl": "Рухаючись за транспортом, що наближається до перехрестя, водій повинен знизити швидкість і бути готовим зупинитися, оскільки ситуація попереду може швидко змінитися.", "explSpecific": "Правильно — «Снизить скорость и быть готовым остановиться, при необходимости». Обгін автомобіля попереду чи наближення впритул до нього — небезпечні маневри саме перед перехрестям, де може виникнути потреба раптово зупинитися.", "img": "q238.png"}, {"num": 239, "text": "Как водитель должен обогнать велосипедиста в этой ситуации?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Обогнать велосипедиста, не пересекая ни одной из линий.", "Пересечь обе линии и держаться ближе к велосипедисту.", "Подать звуковой сигнал предупреждения велосипедисту, которого он собирается обогнать.", "Пересечь пунктирную белую линию."], "correct": 3, "expl": "Обганяючи велосипедиста на дорозі з переривчастою білою лінією, водій може перетнути цю лінію, щоб забезпечити достатню бічну дистанцію — це дозволено правилом переривчастої лінії.", "explSpecific": "Правильно — «Пересечь пунктирную белую линию». Обгін без перетину лінії ризикує залишити замало простору для велосипедиста; перетин ОБОХ ліній чи наближення впритул не відповідають розмітці на зображенні.", "img": "q239.png"}, {"num": 240, "text": "Что значит пунктирная белая линия в центре дороги?", "topic": "Обгін та зміна смуги руху", "options": ["Водитель может наезжать или пересекать пунктирную линию, чтобы объехать препятствия или совершить обгон.", "Водитель не может наезжать или пересекать пунктирную линию, чтобы объехать препятствия или совершить обгон.", "Водитель должен ехать по правой стороне.", "Водитель должен ехать по левой стороне."], "correct": 0, "expl": "Переривчаста біла лінія посередині дороги дозволяє перетин за умови безпеки — для обгону чи об'їзду перешкоди, на відміну від суцільної лінії, яка це забороняє.", "explSpecific": "Правильно — «Водитель может наезжать или пересекать пунктирную линию...». Заборона перетину прямо суперечить самій суті переривчастої лінії; жорстка прив'язка руху лише до правої чи лівої сторони не відповідає гнучкому характеру цієї розмітки.", "img": "q240.png"}, {"num": 241, "text": "Водитель намерен повернуть налево на этом перекрестке. Как он может это сделать?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Повернуть налево перед велосипедистом.", "Пропустить грузовик и велосипедиста.", "Уступить дорогу грузовику.", "Пропустить велосипедиста, прежде чем продолжить поворот налево."], "correct": 3, "expl": "Повертаючи ліворуч, водій повинен спершу пропустити велосипедиста, який перетинає його шлях, і лише потім завершити поворот.", "explSpecific": "Правильно — «Пропустить велосипедиста, прежде чем продолжить поворот налево». Поворот перед велосипедистом небезпечний; пропуск вантажівки чи поступлення дорогою саме вантажівці не відповідають зображеній ситуації, де основна небезпека — велосипедист.", "img": "q241.png"}, {"num": 242, "text": "Чем опасно движение по плохо освещенной улице?", "topic": "Дорожні знаки та розмітка", "options": ["Водители могут видеть только встречный транспорт.", "В темных местах может быть трудно разобрать плохо освещенные транспортные средства.", "Водители могут видеть только транспорт, движущийся перед ними.", "Светофор не будет работать."], "correct": 1, "expl": "На погано освітленій вулиці основна небезпека — це втрата видимості слабко освітлених чи темних транспортних засобів на тлі темряви, а не проблеми зі світлофорами чи зустрічним потоком.", "explSpecific": "Правильно — «В темных местах может быть трудно разобрать плохо освещенные транспортные средства». «Бачити лише зустрічний/лише передній транспорт» надто звужують проблему видимості; «світлофор не працюватиме» не пов'язаний із освітленням вулиці як таким.", "img": "q242.png"}, {"num": 243, "text": "Водитель намерен повернуть направо на этом перекрестке. Как он может это сделать?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Продолжить движение перед мотоциклом и автобусом.", "Остановиться перед мотоциклом.", "Остановиться перед автобусом.", "Остановиться перед/на линии."], "correct": 3, "expl": "Перед знаком STOP водій зобов'язаний повністю зупинитися перед стоп-лінією чи безпосередньо на ній, перш ніж оцінювати ситуацію і продовжувати рух.", "explSpecific": "Правильно — «Остановиться перед/на линии». Продовження руху перед мотоциклом і автобусом чи зупинка саме перед ними (а не на стоп-лінії) не відповідають обов'язковій вимозі знака STOP.", "img": "q243.png"}, {"num": 244, "text": "Водитель намерен повернуть направо на этом перекрестке. Как он может это сделать?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Следовать только за мотоциклом.", "Продолжить движение перед мотоциклом и автобусом.", "Продолжить движение после того, как проедет мотоцикл и автобус.", "Продолжить движение только перед автобусом."], "correct": 2, "expl": "Після обов'язкової зупинки на знаку STOP водій повинен пропустити мотоцикл і автобус, які вже рухаються перехрестям, і лише потім продовжити рух.", "explSpecific": "Правильно — «Продолжить движение после того, как проедет мотоцикл и автобус». Рух лише за мотоциклом, проїзд перед обома транспортними засобами чи проїзд лише перед автобусом — небезпечні чи неповні дії, що ігнорують одного з двох учасників.", "img": "q244.png"}, {"num": 245, "text": "Слева дует сильный ветер. Водитель намерен обогнать грузовик. Когда водитель больше всего подвержен опасности?", "topic": "Погодні умови та видимість", "options": ["При движении транспортного средства против направления ветра.", "При въезде в воздушный поток грузовика.", "При выезде из воздушного потока грузовика.", "При движении транспортного средства в направлении ветра."], "correct": 1, "expl": "Обганяючи вантажівку при сильному боковому вітрі, найнебезпечніший момент — саме в'їзд у повітряний потік і аеродинамічну тінь позаду вантажівки, де раптова зміна тиску повітря може смикнути автомобіль убік.", "explSpecific": "Правильно — «При въезде в воздушный поток грузовика». Рух проти чи за напрямком вітру самостійно не описує момент найбільшої небезпеки; виїзд із повітряного потоку менш небезпечний, ніж різкий вхід у нього.", "img": "q245.png"}, {"num": 246, "text": "Что должен делать водитель, приближаясь к светофору, свет которого меняется с зеленого на желтый?", "topic": "Дорожні знаки та розмітка", "options": ["Ускориться, чтобы освободить перекресток.", "Подать звуковой сигнал при проезде через перекресток.", "Остановиться, если это безопасно.", "Немедленно остановиться."], "correct": 2, "expl": "Коли сигнал світлофора змінюється з зеленого на жовтий, стандартна реакція — зупинитися, якщо це можна зробити безпечно, а не намагатися проскочити перехрестя.", "explSpecific": "Правильно — «Остановиться, если это безопасно». «Прискоритися, щоб звільнити перехрестя» і «проїхати на цей сигнал» суперечать обережному підходу до жовтого сигналу; «подати звуковий сигнал» не є відповідною реакцією на зміну кольору світлофора.", "img": "q246.png"}, {"num": 247, "text": "Каковы действия водителя в случае ослепления светом фар встречного автомобиля?", "topic": "Швидкісний режим", "options": ["Мигнуть встречному автомобилю и съехать влево.", "Посмотрите на левый (ближний) край дороги и, при необходимости, снизить скорость.", "Ускориться, чтобы как можно быстрее выйти из диапазона света фар.", "Ослепить встречный автомобиль дальним светом фар своего автомобиля и съехать вправо."], "correct": 1, "expl": "Осліплений фарами зустрічного авто водій повинен перевести погляд на лівий (ближній) край своєї смуги і за потреби знизити швидкість, а не дивитися на джерело світла.", "explSpecific": "Правильно — «Посмотрите на левый (ближний) край дороги и, при необходимости, снизить скорость». Миготіння фарами у відповідь чи засліплення зустрічного дальнім світлом — агресивні дії; прискорення, щоб швидше виїхати зі сліпучого світла, підвищує ризик зіткнення наосліп.", "img": "q247.png"}, {"num": 248, "text": "Намереваясь повернуть направо, как показано на рисунке, что должен делать водитель автомобиля?", "topic": "Погодні умови та видимість", "options": ["Подождите и дайте грузовику проехать первым.", "Подождите и дайте грузовику и встречному автомобилю проехать первыми.", "Подождите и дайте проехать встречному автомобилю.", "Осторожно продолжайте движение, поскольку у вас преимущество."], "correct": 2, "expl": "Повертаючи праворуч на перехресті, де інший транспорт наближається по пріоритетній дорозі, водій повинен зачекати, поки цей транспорт проїде, перш ніж завершити маневр.", "explSpecific": "Правильно — «Подождите и дайте проехать встречному автомобилю». Очікування вантажівки, яка сама стоїть перед знаком «Уступіть дорогу», не потрібне; продовження руху «за перевагою» ігнорує реальний пріоритет автомобіля з головної дороги.", "img": "q248.png"}, {"num": 249, "text": "Какая опасность может ожидать вас за вершиной холма?", "topic": "Обгін та зміна смуги руху", "options": ["Медленно движущееся транспортное средство может ехать по вашей полосе.", "Обрыв дороги.", "Железнодорожный переезд.", "Озеро."], "correct": 0, "expl": "За вершиною пагорба видимість дороги попереду різко обмежена, тому там може ховатися повільний транспорт саме на вашій смузі.", "explSpecific": "Правильно — «Медленно движущееся транспортное средство может ехать по вашей полосе». «Обрив дороги», «залізничний переїзд» і «озеро» — відповіді на суміжні варіанти цієї ж серії питань.", "img": "q249.png"}, {"num": 250, "text": "Чего водителю следует остерегаться в этой ситуации?", "topic": "Паркування та зупинка", "options": ["Автобус может быть припаркован на конечной остановке.", "Эту дорогу может использовать только автобусы.", "Перед автобусом может находиться автомобиль.", "Автобус может буксировать прицеп."], "correct": 2, "expl": "Наближаючись до автобуса, що зупинився, водій повинен пам'ятати, що перед ним може ховатися ще один автомобіль, непомітний через габарити автобуса.", "explSpecific": "Правильно — «Перед автобусом может находиться автомобиль». Припущення про кінцеву зупинку, ексклюзивність дороги для автобусів чи буксирування причепа — вигадані й малоймовірні деталі.", "img": "q250.png"}, {"num": 251, "text": "Что должен делать водитель, продолжая движение прямо по средней полосе?", "topic": "Обгін та зміна смуги руху", "options": ["Ехать по любой удобной полосе.", "Занять позицию в правом ряду, даже в случае движения право.", "Замедлиться и позволить водителю вас сменить полосу движения.", "Быстро обогнать другие автомобили с правой стороны."], "correct": 2, "expl": "Рухаючись прямо середньою смугою, водій повинен бути готовим уповільнитися й пропустити транспорт, який має намір перестроїтися в його смугу.", "explSpecific": "Правильно — «Замедлиться и позволить водителю вас сменить полосу движения». «Їхати будь-якою зручною смугою» ігнорує конкретну ситуацію; «зайняти праву смугу» і «швидко обігнати справа» — недоречні чи небезпечні маневри.", "img": "q251.png"}, {"num": 252, "text": "О чем должен знать водитель, следуя за мотоциклистом, при том, что белый автомобиль выезжает задним ходом на дорогу?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Водителю, следующему за мотоциклом , может потребоваться больший тормозной путь, чем обычно.", "Водителю на автомобиле, дающему задний ход, остановиться, когда увидит мотоциклиста.", "Стоп-сигналы на мотоциклиста могут не работать.", "Мотоциклист может дать сигнал водителю, дающему задний ход, необходимости остановиться."], "correct": 0, "expl": "Слідуючи за мотоциклістом у ситуації, коли попереду автомобіль здає заднім ходом, водій повинен пам'ятати, що мотоцикліст може загальмувати різкіше й непередбачуваніше, тому самому водієві може знадобитися більший гальмівний шлях.", "explSpecific": "Правильно — «Водителю, следующему за мотоциклом, может потребоваться больший тормозной путь, чем обычно». Обов'язок водія заднього ходу зупинитися чи несправність стоп-сигналів мотоцикла — це дії чи стан інших учасників.", "img": "q252.png"}, {"num": 253, "text": "Что следует делать водителю в данной ситуации?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Снизить скорость и при необходимости, остановиться.", "Увеличьте скорость, чтобы освободить мост перед встречным автомобилем.", "Двигаться дальше, поскольку встречный транспорт должен подождать, пока вы не проедете.", "Уступить дорогу, только если вы буксируете автоприцепом."], "correct": 0, "expl": "Наближаючись до звуженої ділянки дороги (наприклад, вузького мосту чи тунелю), де зустрічний транспорт уже може бути всередині, водій повинен знизити швидкість і за потреби зупинитися, пропускаючи зустрічний транспорт.", "explSpecific": "Правильно — «Снизить скорость и при необходимости, остановиться». Збільшення швидкості, щоб проїхати першим, чи продовження руху з вимогою до зустрічного транспорту чекати — небезпечні дії; поступлення дорогою лише за умови буксирування причепа — вигадане обмеження.", "img": "q253.png"}, {"num": 254, "text": "Почему следует проявлять особую осторожность при движении по брусчатке?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Зазоры между камнями помогают удерживаться стабильно на дороге и улучшают сцепление с дорогой.", "Поверхность дороги особенно ровная, а сцепление шин-лучше.", "Гладкость булыжников помогает улучшить сцепление.", "Поверхность дороги неровная, сцепление с дорогой меняется."], "correct": 3, "expl": "Брукована поверхня (бруківка) нерівна і має інший, часто менший коефіцієнт зчеплення шин, ніж асфальт, тому керованість і гальмування можуть відрізнятися.", "explSpecific": "Правильно — «Поверхность дороги неровная, сцепление с дорогой меняется». Твердження про покращене зчеплення через зазори між камінням чи гладкість бруківки прямо суперечать реальній фізиці нерівної поверхні.", "img": "q254.png"}, {"num": 255, "text": "Почему после сильного ливня водитель должен находиться на большем расстоянии от автомобиля, едущего впереди?", "topic": "Погодні умови та видимість", "options": ["Потому что после дождя колеса вращаются с большей скоростью.", "Потому что после дождя колеса вращаются с меньшей скорость.", "Поскольку требуемый тормозной путь больше.", "Потому что сцепление с дорогой улучшается при намокании."], "correct": 2, "expl": "Після сильної зливи дорожнє покриття залишається мокрим, зчеплення шин знижене, тому гальмівний шлях довший, ніж на сухій дорозі — саме тому потрібна більша дистанція.", "explSpecific": "Правильно — «Поскольку требуемый тормозной путь больше». Твердження про зміну швидкості обертання коліс чи покращення зчеплення при намоканні — фізично необґрунтовані вигадки.", "img": "q255.png"}, {"num": 256, "text": "К чему должен быть готов водитель на этой улице с односторонним движением с припаркованными с обеих сторон транспортными средствами?", "topic": "Обгін та зміна смуги руху", "options": ["Встречному движению, когда водитель обгоняет грузовик.", "У грузовика может быть левостороннее управление.", "На грузовике может не быть правильной маркировки.", "Пешеходам, проходящим между автомобилями."], "correct": 3, "expl": "На вузькій вулиці з одностороннім рухом і припаркованими з обох боків автомобілями головна прихована небезпека — пішоходи, що можуть несподівано вийти на проїжджу частину між припаркованими машинами.", "explSpecific": "Правильно — «Пешеходам, проходящим между автомобилями». Зустрічний рух неможливий на односторонній вулиці за визначенням; твердження про кермо праворуч чи неправильне маркування вантажівки — вигадані деталі.", "img": "q256.png"}, {"num": 257, "text": "Почему водитель должен быть здесь особенно осторожен?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Потому что существует повышенная опасность заноса.", "Потому что с левой стороны может двигаться транспортное средство.", "У автомобиля справа преимущество движения.", "Автомобиль справа, не обязан сигналить."], "correct": 0, "expl": "Певні ділянки дороги (інше покриття, тінь від дерев, волога після дощу) мають підвищений ризик втрати зчеплення шин з дорогою — це причина особливої обережності саме в такому місці.", "explSpecific": "Правильно — «Потому что существует повышенная опасность заноса». Варіанти про транспорт зліва, пріоритет авто справа чи необов'язковість сигналу для авто справа описують geть інші, не пов'язані з ризиком заносу, ситуації.", "img": "q257.png"}, {"num": 258, "text": "Что водителю делать в этой ситуации, если он намеревается повернуть налево?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Остановиться и показать пешеходам, что они могут пройти.", "Уступить дорогу пешеходам, уже переходящим дорогу.", "Подать звуковой сигнал и ускориться, чтобы быстро проехать через переезд.", "Проехать между пешеходами."], "correct": 1, "expl": "Повертаючи ліворуч, водій повинен поступитися дорогою пішоходам, які вже почали переходити проїжджу частину.", "explSpecific": "Правильно — «Уступить дорогу пешеходам, уже переходящим дорогу». Зупинка з жестом дозволу пройти, звуковий сигнал з прискоренням чи проїзд між пішоходами — небезпечні або зайві дії, коли пішоходи вже на дорозі мають пріоритет.", "img": "q258.png"}, {"num": 259, "text": "Что должен делать водитель при повороте направо на этом перекрестке?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Пропустить красный автомобиль.", "Пропустить синий автомобиль.", "Пропустить оба автомобиля.", "Проехать перед обоими автомобилями."], "correct": 0, "expl": "На цьому перехресті червоний автомобіль має перевагу проїзду, тому водій, повертаючи, повинен його пропустити.", "explSpecific": "Правильно — «Пропустить красный автомобиль». Пропуск синього автомобіля, обох автомобілів одразу чи проїзд перед обома — не відповідають зображеній розстановці транспорту, де саме червоний автомобіль перебуває на шляху водія.", "img": "q259.png"}, {"num": 260, "text": "Что нужно знать водителю в этой ситуации?", "topic": "Дорожні знаки та розмітка", "options": ["Замедлиться и приготовиться среагировать.", "Впереди дорожная разметка.", "Впереди дорога переходит в двойную проезжую часть.", "Транспорт, движущийся сзади, может срезать поворот."], "correct": 0, "expl": "У певних дорожніх ситуаціях (наприклад, обмежена видимість чи звужена дорога) головне правило — завчасно знизити швидкість і бути готовим відреагувати на несподіванку.", "explSpecific": "Правильно — «Замедлиться и приготовиться среагировать». Інші варіанти описують конкретні деталі ситуації, тоді як універсально правильна поведінка водія — саме зниження швидкості й готовність до реакції.", "img": "q260.png"}, {"num": 261, "text": "О чем должен знать водитель при движении ночью по торговой улице с множеством разных источников освещения?", "topic": "Дорожні знаки та розмітка", "options": ["Другие транспортные средства не должны использовать фары.", "Из-за яркого света переходов легче увидеть.", "Трудно заметить места для парковки.", "Светофор может быть трудно отличить от других ярких огней."], "correct": 3, "expl": "На торговій вулиці з великою кількістю яскравих вивісок і реклами вночі світлофор може губитися серед іншого освітлення, тому водій має бути особливо уважним, щоб не пропустити сигнал.", "explSpecific": "Правильно — «Светофор может быть трудно отличить от других ярких огней». «Інші ТЗ не повинні використовувати фари» — вигадане й хибне твердження; «легше побачити переходи через яскраве світло» і «важко помітити місця для парковки» не описують головну небезпеку саме світлофора серед вогнів вивісок.", "img": "q261.png"}, {"num": 262, "text": "Чего водителю следует больше всего остерегаться в этой ситуации?", "topic": "Паркування та зупинка", "options": ["Одно из припаркованных транспортных средств может вернуться на путь водителя.", "На вершине холма может неожиданно появиться автомобиль.", "Из-за припаркованных автомобилей могут неожиданно выбежать дети.", "Парковка напротив двойных желтых линий запрещена."], "correct": 2, "expl": "Проїжджаючи повз ряд припаркованих автомобілів у житловому районі, водій повинен найбільше остерігатися дітей, які можуть несподівано вибігти з-за машин.", "explSpecific": "Правильно — «Из-за припаркованных автомобилей могут неожиданно выбежать дети». Повернення одного з припаркованих авто на шлях водія, поява авто на вершині пагорба чи заборона парковки навпроти подвійних жовтих ліній — менш імовірні чи не пов'язані деталі.", "img": "q262.png"}, {"num": 263, "text": "Как водитель должен поступить в этой ситуации?", "topic": "Швидкісний режим", "options": ["Сохранять скорость и не ждать, пока дети пройдут.", "Снизить скорость и приготовиться остановится, так как могут появиться и другие дети.", "Посигналить и продолжать движение.", "Быстро продолжать движение, чтобы не задерживать следующий за вами транспорт."], "correct": 1, "expl": "Побачивши дітей біля дороги, водій повинен знизити швидкість і бути готовим зупинитися, оскільки поблизу можуть з'явитися ще діти.", "explSpecific": "Правильно — «Снизить скорость и приготовиться остановится, так как могут появиться и другие дети». Збереження швидкості без очікування дітей, сигнал з продовженням руху чи прискорення, щоб не затримувати транспорт позаду, — недостатньо обережні реакції.", "img": "q263.png"}, {"num": 264, "text": "В данной ситуации, кто должен подождать?", "topic": "Погодні умови та видимість", "options": ["Встречное транспортное средство должно подождать.", "Ни одно из транспортных средств не должно ждать.", "Водителю за остановившимся фургоном следует подождать.", "Автомобиль, находящийся дальше всего от фургона."], "correct": 2, "expl": "Коли зупинений фургон перекриває вашу смугу, а назустріч наближається транспорт, саме водій за фургоном має зачекати, доки зустрічний потік проїде, перш ніж об'їжджати перешкоду.", "explSpecific": "Правильно — «Водителю за остановившимся фургоном следует подождать». Очікування зустрічного транспорту чи «жоден не повинен чекати» ігнорують те, що саме ваша смуга заблокована; «найдальший від фургона автомобіль» — довільний критерій.", "img": "q264.png"}, {"num": 265, "text": "В данной ситуации, кто должен подождать?", "topic": "Погодні умови та видимість", "options": ["Водитель красного автомобиля должен подождать.", "Оба водителя должны подождать.", "Ни один из водителей не должен ждать.", "Водитель автомобиля на главной дороге должен подождать."], "correct": 0, "expl": "Знак пріоритету показує, що ваша дорога є головною, тому транспорт, який виїжджає з другорядної дороги (тут — червоний автомобіль), зобов'язаний зачекати.", "explSpecific": "Правильно — «Водитель красного автомобиля должен подождать». «Обидва повинні чекати» чи «жоден не повинен чекати» ігнорують чіткий пріоритет головної дороги; «водій на головній дорозі повинен чекати» прямо суперечить суті знаку пріоритету.", "img": "q265.png"}, {"num": 266, "text": "При движении по дороге с трамвайными линиями, почему водитель должен проявлять особую осторожность?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Езда по рельсам может улучшить торможение.", "Езда по рельсам может уменьшить сцепление шин.", "Езда по рельсам может увеличить сцепление шин.", "Езда по рельсам может улучшить рулевое управление."], "correct": 1, "expl": "Металева поверхня трамвайних рейок значно слизькіша за асфальт, особливо у вологу погоду, тому проїзд по них знижує зчеплення шин з дорогою.", "explSpecific": "Правильно — «Езда по рельсам может уменьшить сцепление шин». Твердження про покращення гальмування, зчеплення чи керування прямо суперечать фізичним властивостям слизького металу рейок.", "img": "q266.png"}, {"num": 267, "text": "В этой ситуации может ли водитель обогнать велосипедистов?", "topic": "Обгін та зміна смуги руху", "options": ["Нет. Видимость ограничена.", "Может, так как нет запрещающих знаков.", "Да, так как на данном отрезке двустороннее движение.", "Нет, велосипедистов обгонять нельзя."], "correct": 0, "expl": "На вигині дороги з обмеженою видимістю попереду обгін небезпечний, оскільки водій не може переконатися у відсутності зустрічного транспорту на достатній відстані.", "explSpecific": "Правильно — «Нет. Видимость ограничена». Посилання на відсутність заборонних знаків чи нібито двосторонній рух не скасовують реальну небезпеку обмеженої видимості; заборона «велосипедистів обганяти не можна» невірна як загальне правило.", "img": "q267.png"}, {"num": 268, "text": "К чему водитель должен быть готов в этой ситуации?", "topic": "Обгін та зміна смуги руху", "options": ["Велосипедист может съехать с дороги, чтобы повернуть направо на развязке.", "Приготовиться к обгону велосипедиста.", "Велосипедист может съехать с дороги, чтобы повернуть налево на развязке.", "Велосипедист может развернуться."], "correct": 0, "expl": "Наближаючись до розв'язки чи повороту, де велосипедна доріжка проходить поруч, водій має бути готовим, що велосипедист може з'їхати з дороги вбік, щоб повернути праворуч.", "explSpecific": "Правильно — «Велосипедист может съехать с дороги, чтобы повернуть направо на развязке». «Готуватися до обгону» саме по собі не описує конкретну прогнозовану небезпеку; поворот ліворуч велосипедиста — менш імовірний варіант тут.", "img": "q268.png"}, {"num": 269, "text": "Как водитель должен поступить в этой ситуации?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Ускориться, чтобы освободить переход.", "Позволить пешеходу перейти дорогу.", "Посигналить и продолжить движение.", "Продолжить движение и обогнать синий автомобиль."], "correct": 1, "expl": "На пішохідному переході водій зобов'язаний дати пішоходу спокійно перейти дорогу, а не намагатися проскочити чи обігнати інший транспорт у цей момент.", "explSpecific": "Правильно — «Позволить пешеходу перейти дорогу». Прискорення, щоб звільнити перехід, сигнал з продовженням руху чи обгін синього автомобіля — усе це ігнорує пріоритет пішохода на переході.", "img": "q269.png"}, {"num": 270, "text": "Чего водителю следует остерегаться в этой ситуации?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Впереди крутой уклон дороги.", "Впереди опасный поворот направо.", "Впереди справа второстепенная дорога.", "Впереди слева второстепенная дорога."], "correct": 1, "expl": "Жовтий трикутний знак з вигнутою стрілкою праворуч на узбіччі попереджає про небезпечний поворот дороги саме в правий бік попереду.", "explSpecific": "Правильно — «Впереди опасный поворот направо». «Крутий укіс дороги» описує геть інший символ; «другорядна дорога справа/зліва» стосується перехрестя, а не самого повороту траси.", "img": "q270.png"}, {"num": 271, "text": "К чему водитель должен быть готов в этой ситуации?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Повернуть налево из-за дорожных работ.", "Ехать осторожней, так как впереди заповедник.", "Повернуть налево из-за аварии.", "Впереди могут быть дети."], "correct": 0, "expl": "Ситуативні знаки чи огородження дорожніх робіт попереду можуть змусити транспортний потік звернути з звичайного напрямку — водій має бути готовим до цього заздалегідь.", "explSpecific": "Правильно — «Повернуть налево из-за дорожных работ». «Заповідник» і «аварія» вигадують geть інші причини повороту; «попереду можуть бути діти» не пов'язане із самою причиною повороту ліворуч у цій ситуації.", "img": "q271.png"}, {"num": 272, "text": "Что должен сделать водитель, который хочет повернуть направо в этой ситуации?", "topic": "Обгін та зміна смуги руху", "options": ["Продолжать движение прямо и сделать широкий поворот направо.", "Повернуть направо с левой полосы движения.", "Продолжить движение прямо или повернуть налево.", "Повернуть назад и выехать на правильную полосу."], "correct": 2, "expl": "Якщо водій опинився не в тій смузі для потрібного повороту, найбезпечніше — відмовитися від повороту праворуч цього разу і продовжити рух прямо чи ліворуч, а не намагатися перебудуватися в останню мить.", "explSpecific": "Правильно — «Продолжить движение прямо или повернуть налево». Поворот праворуч з лівої смуги — небезпечне порушення розмітки; розворот посеред перехрестя — хаотичний і небезпечний маневр.", "img": "q272.png"}, {"num": 273, "text": "Какое транспортное средство находится в правильной позиции, чтобы повернуть направо с главной дороги на второстепенную?", "topic": "Загальні правила та поведінка на дорозі", "options": ["2", "1", "3", "4"], "correct": 2, "expl": "Позиція «3» — автомобіль трохи зсунутий ближче до центральної лінії головної дороги перед поворотом праворуч на другорядну, залишаючи місце для транспорту, що продовжує рух прямо ліворуч від нього.", "explSpecific": "Правильно — «3». Автомобіль «2» вже перетнув центральну лінію завчасно, заважаючи зустрічному руху; «1» стоїть на самій другорядній дорозі; «4» розташований занадто далеко позаду, не готовий до маневру.", "img": "q273.png"}, {"num": 274, "text": "Какое транспортное средство находится в правильной позиции, чтобы повернуть налево с второстепенной дороги на главную?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Автомобиль 2 находится в правильном положении чтобы повернуть налево.", "Автомобиль 1 находится в правильном положении чтобы повернуть налево.", "Автомобиль 3 находится в правильном положении чтобы повернуть налево.", "Автомобиль 4 находится в правильном положении чтобы повернуть налево."], "correct": 0, "expl": "Для повороту ліворуч з другорядної дороги на головну водій має розташувати автомобіль якомога ближче до лівого краю своєї смуги, впритул до місця виїзду, щоб мати хороший огляд і плавно влитися в потік.", "explSpecific": "Правильно — «Автомобиль 2» (розташований найближче до лівого краю, впритул до перехрестя). «Автомобиль 1» стоїть трохи правіше й далі від краю; «Автомобиль 3» вже виїхав на головну дорогу під кутом; «Автомобиль 4» вже рухається головною дорогою, а не готується до повороту.", "img": "q274.png"}, {"num": 275, "text": "Какое транспортное средство находится в правильной позиции, чтобы выехать на третий выезд (дорога направо) на этом перекрестке?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Автомобиль 4 находится в правильной позиции чтобы взять 3-тий выход.", "Автомобиль 1 находится в правильной позиции чтобы взять 3-тий выход.", "Автомобиль 3 находится в правильной позиции чтобы взять 3-тий выход.", "Автомобиль 2 находится в правильной позиции чтобы взять 3-тий выход."], "correct": 0, "expl": "Щоб виїхати на третій (найдальший, правий) з'їзд кільцевої розв'язки, водій повинен зайняти правильну смугу заздалегідь при наближенні — саме таку позицію займає автомобіль 4.", "explSpecific": "Правильно — «Автомобиль 4 находится в правильной позиции чтобы взять 3-тий выход». Автомобілі 1, 2 чи 3 перебувають в інших позиціях чи на інших смугах, які не відповідають правильному заїзду на третій вихід.", "img": "q275.png"}, {"num": 276, "text": "Какое транспортное средство находится в правильной позиции, чтобы повернуть направо с второстепенной дороги на главную?", "topic": "Загальні правила та поведінка на дорозі", "options": ["3", "4", "1", "2"], "correct": 2, "expl": "Позиція «1» — автомобіль розташований впритул до лінії видачі дороги на другорядній дорозі, з правого боку своєї смуги, що дає найкращий огляд у обидва боки перед поворотом праворуч на головну дорогу.", "explSpecific": "Правильно — «1». «2» стоїть позаду й лівіше, гірше бачачи дорогу; «3» вже виїхав під кутом на перехрестя завчасно; «4» вже перебуває на головній дорозі, а не готується до повороту.", "img": "q276.png"}, {"num": 277, "text": "Что должен делать водитель в случае крутого уклона дороги впереди?", "topic": "Паркування та зупинка", "options": ["Снизить скорость, держаться левой стороны и остерегаться опасности.", "Увеличить скорость и продвигаться по склону.", "Отъехать, остановиться и включить предупреждающий световой сигнал.", "Двигаться к центру дороги, чтобы избежать столкновения с любыми транспортными средствами, которые могут быть припаркованы слева."], "correct": 0, "expl": "Наближаючись до крутого спуску дороги попереду, водій повинен знизити швидкість, триматися лівого боку і бути готовим до прихованої небезпеки.", "explSpecific": "Правильно — «Снизить скорость, держаться левой стороны и остерегаться опасности». Збільшення швидкості чи зупинка з аварійними вогнями без потреби — недоречні реакції; зміщення до центру дороги суперечить правилу тримання лівого боку."}, {"num": 278, "text": "Что делать водителю, если он видит красный предупреждающий треугольник на дороге?", "topic": "Погодні умови та видимість", "options": ["Водитель должен остановиться и дождаться инструкций.", "Водитель должен убрать треугольник, поскольку он создает препятствие на дороге.", "Водитель должен сохранить скорость, продолжить движение и объехать треугольник.", "Водитель должен снизить скорость и быть готовым к опасности впереди."], "correct": 3, "expl": "Червоний попереджувальний трикутник на дорозі — сигнал про небезпеку чи перешкоду попереду (наприклад, аварію чи поламаний транспорт), встановлений іншим водієм.", "explSpecific": "Правильно — «Снизить скорость и быть готовым к опасности впереди». Прибирання трикутника чужого попередження — неправильне й небезпечне втручання; зупинка й очікування інструкцій чи ігнорування знаку не відповідають адекватній реакції."}, {"num": 279, "text": "Водитель приближается к светофору, на котором некоторое время горит зеленый свет. Как водителю следует поступить?", "topic": "Дорожні знаки та розмітка", "options": ["Водитель должен знать, что свет может измениться, прежде чем он доедет до светофора, и приготовиться остановиться.", "Водитель должен сохранять скорость, пока свет не изменится на желтый.", "Водитель должен остановиться, если свет вот-вот сменится на красный.", "Водитель должен знать, что свет может измениться, и ускориться, чтобы что бы успеть проехать."], "correct": 0, "expl": "Тривало зелений сигнал світлофора не гарантує, що він залишиться зеленим до моменту, коли водій до нього доїде — потрібно бути готовим до зміни сигналу заздалегідь.", "explSpecific": "Правильно — «Водитель должен знать, что свет может измениться... и приготовиться остановиться». «Зберігати швидкість до жовтого» і «прискоритися, щоб встигнути проїхати» — це саме та необережна поведінка, якої правило застерігає уникати; «зупинитися, лише якщо ось-ось зміниться на червоний» звужує завчасну готовність до останньої миті."}, {"num": 280, "text": "Что должен делать водитель, приближаясь к перекрестку, регулируемому светофором, но светофор не работает?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Оперативно проехать через перекресток, чтобы избежать задержки.", "Проехать перекресток как нерегулируемый и действовать осторожно, следя за другим транспортом.", "Включить фары, двигаться к центру перекрестка и проехать как можно быстрее.", "Остановиться на перекрестке и уступить дорогу транспорту слева."], "correct": 1, "expl": "Якщо світлофор на перехресті не працює, водій повинен проїжджати перехрестя як нерегульоване, діючи обережно і стежачи за іншим транспортом.", "explSpecific": "Правильно — «Проехать перекресток как нерегулируемый и действовать осторожно, следя за другим транспортом». Оперативний проїзд, щоб уникнути затримки, рух до центру перехрестя на максимальній швидкості чи обов'язкова зупинка з поступленням дорогою транспорту зліва — небезпечні чи невірні дії."}, {"num": 281, "text": "Что должен делать водитель если на дороге впереди видит скот?", "topic": "Погодні умови та видимість", "options": ["Водитель должен подать звуковой сигнал, включить фары, снизить скорость и осторожно проехать.", "Водитель должен снизить скорость и осторожно проехать.", "Водитель должен включить фары и постараться проехать как можно быстрее.", "Водитель должен посигналить, чтобы заставить скот отойти в сторону."], "correct": 1, "expl": "Побачивши худобу на дорозі, водій має знизити швидкість і обережно проїхати повз, не намагаючись налякати тварин сигналом чи проїхати якнайшвидше.", "explSpecific": "Правильно — «Снизить скорость и осторожно проехать». Звуковий сигнал чи спроба «прогнати» худобу можуть налякати тварин і спричинити непередбачувану реакцію; спроба проїхати якнайшвидше підвищує ризик зіткнення."}, {"num": 282, "text": "Что должен делать водитель если на дороге впереди видит всадников на лошадях?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Водитель должен включить аварийные огни и продолжать движение с нормальной скоростью.", "Водитель должен увеличить скорость и проехать как можно дальше от животных.", "Водитель должен снизить скорость и осторожно проехать как можно дальше от животных.", "Водитель должен снизить скорость и посигналить."], "correct": 2, "expl": "Наближаючись до вершників на конях, водій повинен знизити швидкість і проїхати на максимально можливій відстані, оскільки коні можуть злякатися звуку двигуна чи близькості транспорту.", "explSpecific": "Правильно — «Снизить скорость и осторожно проехать как можно дальше от животных». Увімкнення аварійних вогнів і збереження чи збільшення швидкості можуть налякати тварин ще більше; сигнал клаксоном так само підвищує ризик."}, {"num": 283, "text": "0 чем должен помнить водитель, если увидит на дороге всадников на лошадях?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Водители должны знать, что всадники обязаны слезть с лошади и контролировать лошадь во время проезда мимо них транспортных средств.", "Водители должны знать, что все всадники имеют опыт работы с лошадьми.", "Водители должны знать, что громкий шум автомобиля может испугать лошадь и она может ринуться вперед.", "Водители должны знать, что громкий шум автомобиля не испугает лошадь."], "correct": 2, "expl": "Коні можуть злякатися гучного звуку двигуна чи близькості транспорту і непередбачувано рвонути вперед, тому водій має бути готовим саме до такої реакції тварини.", "explSpecific": "Правильно — «Громкий шум автомобиля может испугать лошадь и она может ринуться вперед». Твердження про обов'язок вершників злазити з коня чи про досвідченість усіх вершників — вигадані припущення; «шум не налякає коня» суперечить реальній поведінці тварин."}, {"num": 284, "text": "Что должен делать водитель, приближаясь к высокому холму?", "topic": "Паркування та зупинка", "options": ["Водитель должен ехать ближе к центру дороги, чтобы избежать столкновения с любыми транспортными средствами, которые могут быть припаркованы слева.", "Водитель должен сохранять нормальную скорость и позицию на дороге.", "Водитель должен снизить скорость, держаться левой стороны и остерегаться опасности.", "Водитель должен увеличить скорость и проехать по высокому холму."], "correct": 2, "expl": "Наближаючись до високого пагорба з обмеженою видимістю за ним, водій повинен знизити швидкість, триматися лівого боку і бути готовим до прихованої небезпеки.", "explSpecific": "Правильно — «Водитель должен снизить скорость, держаться левой стороны и остерегаться опасности». Збереження звичайної швидкості й позиції чи, тим паче, збільшення швидкості перед пагорбом з обмеженою видимістю — небезпечні реакції."}, {"num": 285, "text": "Что должен делать водитель в случае большого разлива масла на дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Сохранять нормальную скорость и попытаться проехать данный участок.", "Снизить скорость, осторожно нажав на тормоза, и включить аварийные огни.", "Отпустить сцепление, резко затормозить и включить аварийные огни.", "Сохранять нормальную скорость на пониженной передаче и включить аварийные огни."], "correct": 1, "expl": "Розлита олива на дорозі різко знижує зчеплення шин з покриттям, тому реагувати потрібно плавно — обережне гальмування та аварійні вогні, щоб попередити транспорт позаду.", "explSpecific": "Правильно — «Снизить скорость, осторожно нажав на тормоза, и включить аварийные огни». Збереження нормальної швидкості чи спроба проїхати ділянку ігнорує ризик втрати зчеплення; різке гальмування чи відпускання зчеплення на слизькій плямі підвищує ризик заносу."}, {"num": 286, "text": "0 чем предупреждают водителя проблесковые маячки встречного автомобиля?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Встречное транспортное средство может двигаться медленно либо быть шире обычного.", "Что встречное транспортное средство движется быстро.", "Что встречное транспортное средство - автомобиль экстренной службы.", "Что встречное транспортное средство -это военный автомобиль."], "correct": 0, "expl": "Проблискові маячки (жовті/помаранчеві) на зустрічному транспорті зазвичай попереджають про повільний, негабаритний чи спеціальний транспортний засіб, а не про екстрені чи військові служби.", "explSpecific": "Правильно — «Встречное транспортное средство может двигаться медленно либо быть шире обычного». Автомобілі екстрених служб і військові машини мають інші спеціальні сигнали; «рухається швидко» суперечить типовому призначенню такого маячка."}, {"num": 287, "text": "Что делать водителю, если он видит автомобиль с желтыми проблесковыми маяками?", "topic": "Паркування та зупинка", "options": ["Остановиться, поскольку это автомобиль экстренной службы.", "Увеличить скорость, но при этом держаться левой стороны.", "Моргнуть фарами, чтобы предупредить о том, что увидел маяки.", "Замедлиться и приготовиться остановиться."], "correct": 3, "expl": "Побачивши автомобіль з жовтими проблисковими маячками (негабаритний чи спеціальний транспорт), водій повинен знизити швидкість і бути готовим зупинитися.", "explSpecific": "Правильно — «Замедлиться и приготовиться остановиться». Обов'язкова зупинка «бо це екстрена служба» помилково трактує жовтий маячок (це не колір екстрених служб); збільшення швидкості чи миготіння фарами — недоречні реакції."}, {"num": 288, "text": "0 чем должен помнить водитель, прежде чем пересечь железнодорожную или трамвайную линию?", "topic": "Загальні правила та поведінка на дорозі", "options": ["При пересечении рельсов может возникнуть шум от шин.", "Колеса могут застрять между рельсами, что приведет к их спуску.", "Сцепление шин может быть улучшено при пересечении рельсов.", "Поверхность может быть неровной, и сцепление шин может быть снижено при пересечении рельсов."], "correct": 3, "expl": "Перед перетином залізничних чи трамвайних колій водій має пам'ятати, що поверхня біля рейок часто нерівна, а зчеплення шин знижене через метал рейок.", "explSpecific": "Правильно — «Поверхность может быть неровной, и сцепление шин может быть снижено». «Шум від шин» — незначний фактор; твердження про покращення зчеплення прямо суперечать фізиці металевих рейок; «колеса можуть застрягти» стосується вужчих трамвайних жолобів."}, {"num": 289, "text": "Что следует знать водителю при пересечении дорожной разметки, такой как линии и стрелки в дождливую погоду?", "topic": "Дорожні знаки та розмітка", "options": ["Сцепление шин улучшается.", "Рулевое управление улучшается.", "Требуемый тормозной путь уменьшается из-за улучшенного сцепления шин.", "Требуемый тормозной путь увеличивается из-за ухудшенного сцепления шин."], "correct": 3, "expl": "Дорожня розмітка (лінії, стрілки) стає слизькою під дощем сильніше, ніж звичайний асфальт, тому що фарба має інший коефіцієнт зчеплення з шинами, ніж дорожнє покриття.", "explSpecific": "Правильно — «Требуемый тормозной путь увеличивается из-за ухудшенного сцепления шин». Варіанти про покращення зчеплення чи керування прямо суперечать фізиці слизької розмітки під дощем; «зменшення тормозного шляху» — протилежний, невірний висновок."}, {"num": 290, "text": "Впереди по тротуару идут пешеходы, а на дороге лужи воды. Как водителю следует поступить?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Посигналить, чтобы предупредить пешеходов, и продолжить движение.", "Снизить скорость и попытаться объехать лужи так, чтобы не забрызгать пешеходов.", "Моргнуть фарами, чтобы предупредить пешеходов.", "Приближаясь к лужам, резко затормозить."], "correct": 1, "expl": "Побачивши попереду калюжі й пішоходів на тротуарі, водій повинен знизити швидкість і спробувати об'їхати калюжі, щоб не обризкати пішоходів.", "explSpecific": "Правильно — «Снизить скорость и попытаться объехать лужи так, чтобы не забрызгать пешеходов». Сигнал клаксоном чи фарами не запобігає бризкам; різке гальмування безпосередньо перед калюжами небезпечне саме по собі."}, {"num": 291, "text": "При подготовке к остановке водитель замечает, что транспортное средство позади буксирует прицеп. Как водителю следует поступить?", "topic": "Паркування та зупинка", "options": ["Своевременно сообщить об этом и двигаться постепенно, чтобы оставить для автомобиля, следующего за ним, дополнительное пространство для тормозного пути.", "Быстро остановиться, не спуская глаз с зеркала заднего вида.", "Временно ускорится, чтобы установить расстояние между своим автомобилем и автомобилем, следующим позади.", "Использовать ручник для замедления и остановки."], "correct": 0, "expl": "Готуючись зупинитися і помітивши, що транспорт позаду буксирує причіп (а отже, має довший гальмівний шлях), водій повинен завчасно просигналізувати й уповільнюватися поступово, залишаючи більше простору.", "explSpecific": "Правильно — «Своевременно сообщить об этом и двигаться постепенно, чтобы оставить дополнительное пространство для тормозного пути». Різка зупинка, штучне прискорення чи використання ручника замість поступового гальмування — небезпечні реакції."}, {"num": 292, "text": "Автобус впереди отъезжает от автобусной остановки. Как водителю следует поступить?", "topic": "Паркування та зупинка", "options": ["Попытаться проехать быстро мимо, чтобы избежать задержки.", "Посигналить водителю автобуса, чтобы он позволил вам проехать.", "Замедлиться, и позволить автобусу выехать.", "Двигаться рядом с ним, поскольку у вас есть преимущественное право проезда."], "correct": 2, "expl": "Коли автобус попереду відʼїжджає від зупинки, водій повинен сповільнитися й дати йому виїхати в потік, виявляючи ввічливість до громадського транспорту.", "explSpecific": "Правильно — «Замедлиться, и позволить автобусу выехать». Спроба проїхати швидко повз чи сигнал водію автобуса не дають автобусу пріоритету, який передбачений правилом; твердження про власне переважне право проїзду поруч з автобусом невірне."}, {"num": 293, "text": "Что должен делать водитель на узкой дороге, когда другой автомобиль едет ему на встречу?", "topic": "Погодні умови та видимість", "options": ["Сохранять позицию и ожидать, пока другой автомобиль не проедет.", "Выехать на середину дороги, чтобы другой водитель понял, что он может проехать.", "Необходимо снизить скорость и обеспечить соответствующее расстояние между своим транспортным средством и встречным.", "Сохранить позицию на дороге и скорость. Затем моргнуть фарами другим транспортным средствам, чтобы предупредить другого водителя о вашем присутствии."], "correct": 2, "expl": "На вузькій дорозі зі зустрічним транспортом головне правило — знизити швидкість і зберегти достатню бічну дистанцію для безпечного роз'їзду.", "explSpecific": "Правильно — «Необходимо снизить скорость и обеспечить соответствующее расстояние». Виїзд на середину дороги для «сигналу» іншому водієві чи збереження швидкості з миганням фар — небезпечні й неоднозначні дії на вузькій дорозі."}, {"num": 294, "text": "Что делать водителю, когда едет вперед и хочет остановиться у магазина на другой стороне улицы?", "topic": "Паркування та зупинка", "options": ["Припарковаться на безопасной парковке.", "Съехать на другую сторону.", "Включить поворот и развернуть машину.", "Припарковать автомобиль напротив магазина."], "correct": 0, "expl": "Якщо водій хоче зайти в магазин на протилежному боці вулиці, правильна дія — припаркуватися в безпечному місці і перейти дорогу пішки, а не намагатися під'їхати впритул до магазину.", "explSpecific": "Правильно — «Припарковаться на безопасной парковке». З'їзд на протилежний бік дороги, розворот чи паркування прямо навпроти магазину — менш безпечні альтернативи."}]);
